quests[62793] = { id = 62793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es kommt alles zusammen", description = "Der Kampf gegen die Verschmähten, die Bewahrung der Ordnung unter den Aspiranten, die auf den Aufstieg warten und unzählige andere Pflichten halten unsere Brüder und Schwestern auf Trab.\n\nDie von Euch aus dem Schlund geborgenen bereitwilligen Seelen werden uns in diesen düsteren Zeiten von großem Nutzen sein.\n\nBegebt Euch gleich zu Haephus. Er sucht für seine Bestrebungen, die mächtigsten Eigenschaften des Sanktums zu aktivieren, schon länger nach Unterstützung. Es wird Zeit, das volle Potenzial der Elysischen Feste zum Vorschein zu bringen.", sourceObjective = "Sprecht mit Haephus.", completion = "Als Ihr sie zur Feste brachtet, konnte ich ihre Präsenz spüren. Welch bedeutender Augenblick!", sourceObjectiveStatus = "unverified-source-field" }
quests[62794] = { id = 62794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verbesserung der Festung", description = "Als Dank für Eure Bemühungen, die Anima und die Seelen zu bergen, könnt Ihr jetzt entscheiden, welche Funktionen der Elysischen Feste wir zuerst verbessern sollen.\n\nSo können wir nicht nur die Bastion besser unterstützen, sondern auch die gesamten Schattenlande.\n\nKeine Sorge, je mehr Anima und bereitwillige Seelen Ihr bergt, desto mehr Funktionen werden wir mit der Zeit aktivieren können. Fürs Erste muss eine einzige Aufwertung reichen.", sourceObjective = "Beginnt eine Sanktumaufwertung.", completion = "Eine weise Entscheidung. Die Aktivierung wird etwas dauern, doch gut Ding will Weile haben, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[62795] = { id = 62795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Medium für das Gute", description = "Die Gaben Eures Bandes sind außerordentlich, Ihr könnt sie aber durch den Einsatz von Medien noch weiter stärken.\n\nMedien fokussieren die Energie Eures Seelenbands direkter und erhöhen so Euer Potenzial auf schier unendliche Art und Weise.\n\nNutzt die, die ich Euch gegeben habe, um diese Macht zu testen, aber keine Angst... Während Eurer Hilfe für die Schattenlande werdet Ihr weitere finden.", sourceObjective = "Fügt der Schmiede der Bande die Medien hinzu und setzt dann eins davon in einen freien Platz bei Pelagos ein.", completion = "Euer Seelenband wird mit der Zeit wachsen, doch fürs Erste ist Euer Training beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62796] = { id = 62796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zu Adrestes", description = "Baine leidet in Torghast, aber zumindest wissen wir jetzt, dass er noch lebt.\n\nOhne einen Angriffsplan zu seiner Rettung zu eilen, wäre jedoch zum Scheitern verurteilt. Lasst mich einen ausarbeiten.\n\nIn der Zwischenzeit könnt Ihr die Seelen, die Ihr gerettet habt, zur Elysischen Feste bringen.\n\nDie Schattenlande brauchen die Kyrianer. Falls die Bastion in Aufruhr bleibt, könnte bald alles verloren sein.", sourceObjective = "Meldet Euch bei Polemarch Adrestes in der Elysischen Feste in der Bastion.", completion = "Willkommen zurück, Schlundgänger. Wir haben während Euer Abwesenheit nicht geruht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62797] = { id = 62797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefäße des Metalls", description = "Ihr scheint mit der Schmiedekunst vertraut zu sein. Doch man lernt nie aus.\n\nJemand wie Ihr sollte Gefäße anfertigen können, in denen die Macht der Runen ruht. Dies kann ich Euch jedoch nicht beibringen.\n\nHmm, doch, es gibt einen Weg. Ich werde Euch eine Erinnerung mit den Plänen für die Gefäße anvertrauen. Bringt sie zu einem Meister Euer Kunst, dann zeigt er Euch den Rest.\n\nWie meint Ihr? Keine Sorge. Es ist lediglich ein Echo meiner Erinnerung. Was Ihr wiederherstellt, bleibt intakt.", sourceObjective = "Bringt die Erinnerung zurück zu Schmied Au'berk in Oribos.", completion = "<Au'berk betrachtet, was Ihr ihm präsentiert.>\n\nEine Erinnerung. Faszinierend... Mit diesem Wissen kann ich Euch lehren, Rüstung von immenser Macht anzufertigen. \n\nDas kostet natürlich etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[62798] = { id = 62798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefäße von Leder und Knochen", description = "Ihr scheint mit der Lederverarbeitung vertraut zu sein. Doch man lernt nie aus.\n\nJemand wie Ihr sollte Gefäße anfertigen können, in denen die Macht der Runen ruht. Dies kann ich Euch jedoch nicht beibringen.\n\nHmm, doch, es gibt einen Weg. Ich werde Euch eine Erinnerung mit den Plänen für die Gefäße anvertrauen. Bringt sie zu einem Meister Euer Kunst, dann zeigt er Euch den Rest.\n\nWie meint Ihr? Keine Sorge. Es ist lediglich ein Echo meiner Erinnerung. Was Ihr wiederherstellt, bleibt intakt.", sourceObjective = "Bringt die Erinnerung zurück zum Gerber Au'qil in Oribos.", completion = "<Au'qil betrachtet, was Ihr ihm präsentiert.>\n\nEine Erinnerung. Faszinierend... Mit diesem Wissen kann ich Euch lehren, Rüstung von immenser Macht anzufertigen. \n\nDas kostet natürlich etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[62799] = { id = 62799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefäße des Fadens", description = "Ihr scheint mit der Flickkunst vertraut zu sein. Doch man lernt nie aus.\n\nJemand wie Ihr sollte Gefäße anfertigen können, in denen die Macht der Runen ruht. Dies kann ich Euch jedoch nicht beibringen.\n\nHmm, doch, es gibt einen Weg. Ich werde Euch eine Erinnerung mit den Plänen für die Gefäße anvertrauen. Bringt sie zu einem Meister Euer Kunst, dann zeigt er Euch den Rest.\n\nWie meint Ihr? Keine Sorge. Es ist lediglich ein Echo meiner Erinnerung. Was Ihr wiederherstellt, bleibt intakt.", sourceObjective = "Bringt die Erinnerung zurück zum Flicker Au'phes in Oribos.", completion = "<Au'phes betrachtet, was Ihr ihm präsentiert.>\n\nEine Erinnerung. Faszinierend... Mit diesem Wissen kann ich Euch lehren, Rüstung von immenser Macht anzufertigen. \n\nDas kostet natürlich etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[62800] = { id = 62800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gefäße der Edelsteine", description = "Ihr scheint mit der Edelsteinschleiferei vertraut zu sein. Doch selbst <ein Juwelenschleifer/eine Juwelenschleiferin> lernt nie aus.\n\nJemand wie Ihr sollte Gefäße anfertigen können, in denen die Macht der Runen ruht. Dies kann ich Euch jedoch nicht beibringen.\n\nHmm, doch, es gibt einen Weg. Ich werde Euch eine Erinnerung mit den Plänen für die Gefäße anvertrauen. Bringt sie zu einem Meister Euer Kunst, dann zeigt er Euch den Rest.\n\nWie meint Ihr? Keine Sorge. Es ist lediglich ein Echo meiner Erinnerung. Was Ihr wiederherstellt, bleibt intakt.", sourceObjective = "Bringt die Erinnerung zurück zum Gutachter Au'vesk in Oribos.", completion = "<Au'vesk betrachtet, was Ihr ihm präsentiert.>\n\nEine Erinnerung. Faszinierend... Mit diesem Wissen kann ich Euch lehren, Juwelen von immenser Macht anzufertigen. \n\nDas kostet natürlich etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[62801] = { id = 62801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf des Schicksals", description = "Ich bin der richterliche Schicksalsschreiber. Es ist meine Pflicht, die Stränge des Schicksals zu erkennen, die wundersamen Möglichkeiten der Vorsehung.\n\nDas Schicksal umfließt Euch, <Sterblicher/Sterbliche>, während Ihr durch die Schattenlande zieht. Und jetzt stellt es Euch vor... eine Wahl.\n\nKehrt nach Oribos zurück, {name}, damit ich Euch den Pfad weisen kann.\n\nDie Vorsehung ist unser Weg.", sourceObjective = "Trefft Euch mit dem Schicksalsschreiber Roh-Tahl in Oribos.", completion = "Willkommen, Sterblicher.\n\nErlaubt mir, Euch die Wahl zu erläutern, vor die die Vorsehung Euch stellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62804] = { id = 62804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befüllung der Behälter", description = "<Der Eindämmungsrucksack scheint intakt, aber leer zu sein. Füllt ihn mit der entsprechenden Mixtur von Flüssigkeiten, damit er wieder zu gebrauchen ist.\n\nErledigt die dazu passenden Schleime, um die Flüssigkeiten zu erhalten.>", sourceObjective = "Tötet die verschiedenen Schleime, um die Behälter mit Flüssigkeit zu füllen.", completion = "Ein fantastischer Fund! Ihr habt eine voll aufgeladene Einheit gefunden... Betätigt diesen Schalter, um sie zu aktivieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[62807] = { id = 62807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wald-Flüchtlinge", description = "Manche, die durch den Fall der Haine obdachlos wurden, haben sich nahe beim Herz des Waldes niedergelassen.\n\nDas Winterschlafbecken kann sich glücklich schätzen. Wir haben Vorräte, sie jedoch nicht.\n\nWürdet Ihr diese zu Flwngyrr bringen? Sie kümmern sich dort um die Flüchtlinge.", sourceObjective = "Bringt die Vorräte des Winterschlafbeckens zu Flwngyrr im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Viele Schreie hallen durch die Nacht. Viele Kreaturen suchen Schutz.\n\nDies ist ein erfrischender Hauch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62832] = { id = 62832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freunde an dunklen Orten", description = "Trotz all Eurer Hilfe wird unser Sanktum ohne bereitwillige Seelen schwächer.\n\nViele für die Bastion bestimmte Seelen sind im Schlund gefangen. Wenn Ihr sie irgendwie befreien könntet, würden sie uns beim Wiederaufbau der Elysischen Feste unterstützen.\n\nFindet jede mögliche Hilfe und bewirkt, was wir nicht bewirken können, <Schlundgänger/Schlundgängerin>. Unsere Zukunft könnte davon abhängen.", sourceObjective = "Findet Ve'nari im Schlund.", completion = "So schnell zurück, Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[62833] = { id = 62833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Held von hohem Ruhm", description = "Je höher Euer Ruhm in den Schattenlanden steigt, desto mehr Leute überzeugt Ihr von Eurer Sache. Manche bieten Ressourcen, andere direkte Unterstützung.\n\nElsbeth Larink wird dafür sorgen, dass diese Beiträge Verwendung finden. Sprecht mit ihr, um mehr zu erfahren.", sourceObjective = "Sprecht mit Elsbeth Larink.", completion = "Um der Seelen willen, die wir verteidigen, dürfen wir niemals wanken.", sourceObjectiveStatus = "unverified-source-field" }
quests[62834] = { id = 62834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glorreicher Ehrgeiz", description = "Der durch Eure Taten erlangte Ruhm wird für unseren Pakt von großem Nutzen sein. Unser Ehrgeiz macht schließlich nicht vor den Grenzen von Maldraxxus Halt.\n\nErlaubt mir, Euch zu demonstrieren, was wir mit Ruhm erreichen können.", sourceObjective = "Untersucht Eure Ruhmstufe beim Pakt der Nekrolords.", completion = "Wer aufgibt, ist endgültig gescheitert.", sourceObjectiveStatus = "unverified-source-field" }
quests[62835] = { id = 62835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Hilfe", description = "Wir halten zwar den Sitz des Primus, doch ohne die Anima, um ihn zu versorgen, ist er nutzlos.\n\nHaltet während des Kampfes an der Seite unserer Truppen nach Anima Ausschau, um unsere Kriegsanstrengungen zu unterstützen.\n\nSprecht mit Unteroffizier Romark. Er bietet Euch zusätzlichen Rat.", sourceObjective = "Sprecht mit Unteroffizier Romark.", completion = "Es gibt viel zu tun, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[62836] = { id = 62836, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren des Löwen", description = "Dank Eurer Bemühungen sind Thrall, Jaina Prachtmeer und Baine Bluthuf in Sicherheit. Doch ich fürchte, dass der Kerkermeister Macht über uns hat, solange er auch nur einen Helden Azeroths festhält.\n\nEs scheint, dass Anduin tiefer in den Turm verschleppt wurde als die anderen. Bevor ich es riskiere, einen Blick hineinzuwerfen, müsst Ihr einen letzten Versuch unternehmen, ihn zu finden.\n\nIhr sagt, der Kerkermeister habe davon gesprochen, eine Waffe zu schärfen. Ich fürchte, uns läuft die Zeit davon.\n\nGebt nicht nach, {name}. Durchsucht die verwinkelten Gänge von Torghast nach einem Hinweis auf den jungen Löwen.", sourceObjective = "Betretet Torghast und durchsucht die Gewundenen Korridore nach einer Spur von Anduin Wrynn.", progress = "Habt Ihr irgendeine Spur von Anduin finden können?", completion = "Es gibt drei sichere Anzeichen für Anduins Anwesenheit, und doch ist er nirgendwo zu sehen.\n\nDas sind wirklich schlimme Nachrichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62837] = { id = 62837, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnungsvolle Neuigkeiten", description = "Die Bedingungen unseres Handels sind erfüllt. Ihr dürft mit Euren erlangten Seelen aufbrechen.\n\nVielleicht ist das Schicksal dieses Gefährten \"Baine\" für Euch oder Eure Verbündeten von Wichtigkeit. Ich schlage vor, Ihr kehrt nach Oribos zurück, um Euch mit ihnen zu beraten.\n\nKeine Eile, letztendlich leiden die in Torghast Gefangenen sowieso schon jahrhundertelang.\n\nOh, und denkt bitte daran, niemandem von unserer Vereinbarung zu erzählen. Letztendlich ist Diskretion zwischen Geschäftspartnern äußerst wichtig.", sourceObjective = "Sprecht mit Bolvar Fordragon in Oribos.", completion = "{name}! Die Dunkelheit des Schlunds umgibt Euch. Was bringt Ihr für Neuigkeiten?", sourceObjectiveStatus = "unverified-source-field" }
quests[62839] = { id = 62839, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima ist Stärke", description = "Ihr wart siegreich, <Schlundgänger/Schlundgängerin>. Und mit Eurem Erfolg werden unsere Kräfte stärker.\n\nBleibt wachsam. Eure Stärke wird bald wieder vonnöten sein.\n\nBringt die geborgene Anima rasch zu Arkadia Moa. Sie wird sie sicher verwahren.", sourceObjective = "Sprecht mit Arkadia Moa.", completion = "Der Sturm des Sieges zieht mit Euch, Schlundgänger. Bringt Ihr Anima?", sourceObjectiveStatus = "unverified-source-field" }
quests[62840] = { id = 62840, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir wartet", description = "Da Anima Mangelware ist, hat Baronin Draka mich damit beauftragt, unsere Reserven zu verwalten.\n\nIhr könnt Eure gefundene Anima in diesem Reservoir hier lagern. Die Nekrolords werden sie um jeden Preis verteidigen.", sourceObjective = "Lagert Anima in das Reservoir Eures Sanktums ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62843] = { id = 62843, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenkontakt", description = "Euer Ruf eilt Euch voraus, <Schlundgänger/Schlundgängerin>... Ihr trotzt dem Schlund und bringt Baron Mograine in einem Stück zurück...\n\nHöchst beeindruckend!\n\nBei unserer fatalen Knappheit an Seelen müsst Ihr das unbedingt wiederholen. Bringt uns mehr bereitwillige Seelen, damit wir die Macht des Sanktums wiederherstellen können!\n\nFindet die Mittlerin, die Euch schon einmal geholfen hat, und bittet sie erneut um Unterstützung. Ihr könntet sie brauchen.", sourceObjective = "Sprecht mit Ve'nari im Schlund.", completion = "So schnell zurück, Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[62844] = { id = 62844, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Draka", description = "Baine leidet in Torghast, aber zumindest wissen wir jetzt, dass er noch lebt.\n\nOhne einen Angriffsplan zu seiner Rettung zu eilen, wäre jedoch zum Scheitern verurteilt. Ich werde tun, was ich kann, um einen auszuarbeiten.\n\nIn der Zwischenzeit bittet Euch Baronin Draka per Nachricht, zum Sitz des Primus zurückzukehren.\n\nDie Nekrolords sind der Schlüssel zur Rettung der Schattenlande, {name}. Ihr solltet so bald wie möglich zurückkehren.", sourceObjective = "Meldet Euch bei Baronin Draka im Sitz des Primus in Maldraxxus.", completion = "Ihr seid zurück, Schlundgänger. \n\nGut. Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[62845] = { id = 62845, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles zusammen", description = "Mit all den Häusern als Gegner fällt es unseren Streitkräften schwer, die Stellung zu halten.\n\nDie von Euch aus dem Schlund geretteten Seelen stärken die Verteidigung unserer Position.\n\nBringt sie zu Arkadia Moa. Sie weiß sie am besten zu verwenden, um unser Sanktum zu stärken.", sourceObjective = "Sprecht mit Arkadia Moa.", completion = "Als Ihr sie herbrachtet, konnte ich ihre Präsenz spüren. Ihr Potenzial wird unsere Macht verstärken!", sourceObjectiveStatus = "unverified-source-field" }
quests[62846] = { id = 62846, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbesserungen am Sanktum", description = "Euer Siegeswille ist stark, <Schlundgänger/Schlundgängerin>. Dank der geborgenen Seelen können wir nun auf das wahre Potenzial unseres Sanktums zugreifen.\n\nJe mehr Seelen und Anima wir erlangen, desto mächtiger wird der Sitz des Primus. Strebt unerbittlich weiter, dann werden wir siegreich sein.", sourceObjective = "Beginnt eine Sanktumaufwertung.", completion = "Bei solchen Angelegenheiten ist Geduld so wichtig wie Stärke. Mit der Zeit wird unsere Macht zu unübertroffener Größe heranwachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62848] = { id = 62848, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wozu dienen Medien?", description = "Die Vorteile der Seelenbindung sind beträchtlich, Ihr könnt sie aber durch den Einsatz von Medien noch weiter stärken.\n\nMedien fokussieren die Anima unseres Bandes auf vielfältige Weise und erhöhen so unser beider Potenzial ungemein.\n\nLasst uns die Medien ausprobieren, die ich Euch gegeben habe. Aber keine Angst... viele gleichartige können in den Schattenlanden gefunden werden.", sourceObjective = "Fügt der Schmiede der Bande die Medien hinzu und setzt dann eins davon in einen freien Platz bei Seuchenerfinder Marileth ein.", progress = "Dies ist eine wichtige Lektion, Lehrling.", completion = "Unsere Bindung wird immer stärker werden, aber fürs Erste ist Euer Training beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62849] = { id = 62849, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Hofes der Ernter", sourceObjective = "Sprecht mit Herrin Mihaela in Dunkelhafen.", completion = "Versteht dies als erste von vielen unserer Belohnungen für Eure weiteren Anstrengungen. Eure Mühen im Dienste des Hofes der Ernter werden Revendreth den langfristigen Erfolg sichern, und Euch winkt zusätzlicher Lohn.", sourceObjectiveStatus = "unverified-source-field" }
quests[62850] = { id = 62850, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Aufgestiegenen", sourceObjective = "Sprecht mit Adjutantin Nikos in Heldenrast in der Bastion.", completion = "Erfüllt weiter die Ziele der Aufgestiegen, und Euch erwarten weitere Schätze.", sourceObjectiveStatus = "unverified-source-field" }
quests[62851] = { id = 62851, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Unvergänglichen Armee", description = "Eure andauernden Bestrebungen im Dienste der Unvergänglichen Armee bringen Euch den anhaltenden Respekt unserer Truppen ein. \n\nIch wurde autorisiert, Euch zum Dank einen Teil unserer jüngsten Kriegsbeute zu geben. Bitte kommt zum Sitz des Primus, um die Beute einzusammeln, sobald Ihr Zeit habt.", sourceObjective = "Sprecht mit Nalcorn Talsen im Theater der Schmerzen.", completion = "Die Unvergängliche Armee grüßt Euch und bietet Euch diese Kriegsbeute zu Ehren Eurer fortgesetzten Bestrebungen. Helft uns weiter, dann gibt es noch mehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[62852] = { id = 62852, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion der Wilden Jagd", description = "Gut gemacht, {name}!\n\nIhr habt Euch gegenüber ganz Ardenwald als würdig erwiesen. Wir möchten Euch für Eure gerissene Kühnheit weiter belohnen.\n\nTrefft mich im Herz des Waldes.", sourceObjective = "Sprecht mit Aithlyn beim Herz des Waldes.", completion = "Setzt Euch weiter für uns ein, dann werden wir Euch weiter belohnen. Ich bin gespannt auf Eure nächsten Taten!", sourceObjectiveStatus = "unverified-source-field" }
quests[62855] = { id = 62855, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edikt der Ewigen", description = "Ihr sterbt nicht so wie andere, <Schlundgänger/Schlundgängerin>. Doch leider habt Ihr etwas von Eurer Stygia verloren.\n\nKehrt zum Ort Eures Todes zurück, um sie wieder einzusammeln.", sourceObjective = "Bergt Eure fallen gelassene Stygia von Eurer Leiche.", sourceObjectiveStatus = "unverified-source-field" }
quests[62856] = { id = 62856, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wege zum Ruhm", description = "Je mehr Ihr den Hof auf Euren Reisen durch die Schattenlande unterstützt, desto stärker wird unsere Verbindung.\n\nMit der Zeit werdet Ihr von den Vorteilen Eures wachsenden Ruhms profitieren.\n\nEine meiner treuesten und ergebensten Anhängerinnen, Rahel, beobachtet Euch schon seit geraumer Zeit. Sie kann Euch mehr über Euer Ansehen und den Ruhm, den Ihr bei unseren Leuten genießt, erzählen.\n\nSprecht mit ihr, damit sie Euch erklären kann, wie Ihr diesen Ruhm nutzen könnt.", sourceObjective = "Sprecht mit Rahel.", completion = "Wenn Ihr mit mir zusammenarbeitet, wird Eure Legende Teil der Wachträume aller Venthyr in Revendreth sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62857] = { id = 62857, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Beute des Hofes", description = "Venthyr werden von neuen Dingen angezogen, also machen wir Euch zur Galionsfigur unseres Sanktums.\n\nWährend Euer Ruhm in den Schattenlanden wächst, profitieren wir davon, indem wir Macht und Einfluss erlangen, die uns ansonsten nicht zufallen würden.\n\nEs ist meine Aufgabe, Eure Ruhmstufe im Auge zu behalten und diese als Ressource zu quantifizieren. Die wahre Währung der Höfe, wenn Ihr so wollt.\n\nPasst auf.", sourceObjective = "Untersucht Eure Ruhmstufe in Sündensturz.", completion = "Wie Ihr seht, haben einige Leute schon Notiz von Euch genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62858] = { id = 62858, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund. Solange das nicht aufhört, müssen wir so viele wie möglich retten.\n\nDer Kerkermeister verdreht den Kreislauf von Leben und Wiedergeburt. Das darf so nicht weitergehen. Wir müssen seine Pläne durchkreuzen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Oh, wunderbare Neuigkeiten!\n\nIch werde dafür sorgen, dass diese Seelen hier im Ardenwald gut versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62859] = { id = 62859, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund. Solange das nicht aufhört, müssen wir so viele wie möglich retten.\n\nDer Kerkermeister verdreht den Kreislauf von Leben und Wiedergeburt. Das darf so nicht weitergehen. Wir müssen seine Pläne durchkreuzen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Oh, wunderbare Neuigkeiten!\n\nIch werde dafür sorgen, dass diese Seelen hier im Ardenwald gut versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62860] = { id = 62860, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund. Solange das nicht aufhört, müssen wir so viele wie möglich retten.\n\nDer Kerkermeister verdreht den Kreislauf von Leben und Wiedergeburt. Das darf so nicht weitergehen. Wir müssen seine Pläne durchkreuzen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Oh, wunderbare Neuigkeiten!\n\nIch werde dafür sorgen, dass diese Seelen hier im Ardenwald gut versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62861] = { id = 62861, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund und umgehen die natürliche Ordnung der Schattenlande.\n\nDer Kerkermeister verwehrt diesen Seelen ihre rechtmäßige Ewigkeit. Nur Ihr, <Schlundgänger/Schlundgängerin>, könnt die Dinge wieder in Ordnung bringen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet 10 Seelen aus dem Schlund.", completion = "Gut gemacht. Ihnen wurde eine wahrhaft grausame Existenz erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[62862] = { id = 62862, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund und umgehen die natürliche Ordnung der Schattenlande.\n\nDer Kerkermeister verwehrt diesen Seelen ihre rechtmäßige Ewigkeit. Nur Ihr, <Schlundgänger/Schlundgängerin>, könnt die Dinge wieder in Ordnung bringen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet 15 Seelen aus dem Schlund.", completion = "Gut gemacht. Ihnen wurde eine wahrhaft grausame Existenz erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[62863] = { id = 62863, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund und umgehen die natürliche Ordnung der Schattenlande.\n\nDer Kerkermeister verwehrt diesen Seelen ihre rechtmäßige Ewigkeit. Nur Ihr, <Schlundgänger/Schlundgängerin>, könnt die Dinge wieder in Ordnung bringen.\n\nKehrt zum Schlund zurück und rettet, so viele Ihr könnt.", sourceObjective = "Rettet 20 Seelen aus dem Schlund.", completion = "Gut gemacht. Ihnen wurde eine wahrhaft grausame Existenz erspart.", sourceObjectiveStatus = "unverified-source-field" }
quests[62864] = { id = 62864, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "<Schlundgänger/Schlundgängerin>, ich bin sicher, Ihr habt die Seelen, die weiterhin in den Schlund strömen, mit eigenen Augen gesehen.\n\nWir müssen jetzt handeln und dem Kerkermeister die Macht entziehen, indem wir ihm so viele Seelen wie möglich verwehren. Diese Macht gehört den Nekrolords.\n\nIch werde Eure Bemühungen lenken, diese Seelen zu retten, und dabei helfen, für sie einen Platz in den Armeen von Maldraxxus zu finden.\n\nKehrt zum Schlund zurück und rettet diejenigen, die Ihr retten könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Ausgezeichnet, Schlundgänger. Unsere Armeen hier werden mit jeder Seele, die Ihr zurückbringt, stärker werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62865] = { id = 62865, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "<Schlundgänger/Schlundgängerin>, ich bin sicher, Ihr habt die Seelen, die weiterhin in den Schlund strömen, mit eigenen Augen gesehen.\n\nWir müssen jetzt handeln und dem Kerkermeister die Macht entziehen, indem wir ihm so viele Seelen wie möglich verwehren. Diese Macht gehört den Nekrolords.\n\nIch werde Eure Bemühungen lenken, diese Seelen zu retten, und dabei helfen, für sie einen Platz in den Armeen von Maldraxxus zu finden.\n\nKehrt zum Schlund zurück und rettet diejenigen, die Ihr retten könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Ausgezeichnet, Schlundgänger. Unsere Armeen hier werden mit jeder Seele, die Ihr zurückbringt, stärker werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62866] = { id = 62866, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "<Schlundgänger/Schlundgängerin>, ich bin sicher, Ihr habt die Seelen, die weiterhin in den Schlund strömen, mit eigenen Augen gesehen.\n\nWir müssen jetzt handeln und dem Kerkermeister die Macht entziehen, indem wir ihm so viele Seelen wie möglich verwehren. Diese Macht gehört den Nekrolords.\n\nIch werde Eure Bemühungen lenken, diese Seelen zu retten, und dabei helfen, für sie einen Platz in den Armeen von Maldraxxus zu finden.\n\nKehrt zum Schlund zurück und rettet diejenigen, die Ihr retten könnt.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Ausgezeichnet, Schlundgänger. Unsere Armeen hier werden mit jeder Seele, die Ihr zurückbringt, stärker werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62867] = { id = 62867, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund.\n\nIhre Anima, das Lebensblut der Schattenlande, entschwindet mit diesen Seelen, um den Kerkermeister zu nähren. Ihr habt mich aus dem Schlund gerettet. Ich sehe keinen Grund, warum Ihr diesem Abgrund nicht noch mehr Seelen entreißen könnt.\n\nBringt mir Seelen, die Ihr aus dem Schlund rettet, und ich sorge dafür, dass sie eine bessere Verwendung finden. In Revendreth haben sie wenigstens eine Chance auf Erlösung.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Eine ausgezeichnete Sammlung von Seelen, nicht zu gebrochen, nicht zu ausgelaugt und nicht zu unschuldig.\n\nSeid unbesorgt, ihr Schicksal liegt besser in unseren Händen als in denen des Kerkermeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[62868] = { id = 62868, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund.\n\nIhre Anima, das Lebensblut der Schattenlande, entschwindet mit diesen Seelen, um den Kerkermeister zu nähren. Ihr habt mich aus dem Schlund gerettet. Ich sehe keinen Grund, warum Ihr diesem Abgrund nicht noch mehr Seelen entreißen könnt.\n\nBringt mir Seelen, die Ihr aus dem Schlund rettet, und ich sorge dafür, dass sie eine bessere Verwendung finden. In Revendreth haben sie wenigstens eine Chance auf Erlösung.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Eine ausgezeichnete Sammlung von Seelen, nicht zu gebrochen, nicht zu ausgelaugt und nicht zu unschuldig.\n\nSeid unbesorgt, ihr Schicksal liegt besser in unseren Händen als in denen des Kerkermeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[62869] = { id = 62869, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr der verlorenen Seelen", description = "Immer mehr Seelen strömen in den Schlund.\n\nIhre Anima, das Lebensblut der Schattenlande, entschwindet mit diesen Seelen, um den Kerkermeister zu nähren. Ihr habt mich aus dem Schlund gerettet. Ich sehe keinen Grund, warum Ihr diesem Abgrund nicht noch mehr Seelen entreißen könnt.\n\nBringt mir Seelen, die Ihr aus dem Schlund rettet, und ich sorge dafür, dass sie eine bessere Verwendung finden. In Revendreth haben sie wenigstens eine Chance auf Erlösung.", sourceObjective = "Rettet Seelen im Schlund.", completion = "Eine ausgezeichnete Sammlung von Seelen, nicht zu gebrochen, nicht zu ausgelaugt und nicht zu unschuldig.\n\nSeid unbesorgt. Ihr Schicksal liegt besser in unseren Händen als in denen des Kerkermeisters.", sourceObjectiveStatus = "unverified-source-field" }
quests[62870] = { id = 62870, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen für Sündensturz", description = "Baine leidet in Torghast, aber zumindest wissen wir jetzt, dass er noch lebt.\n\nOhne einen Angriffsplan zu seiner Rettung zu eilen, wäre jedoch zum Scheitern verurteilt. Lasst mich etwas ausarbeiten.\n\nIn der Zwischenzeit könnt Ihr die Seelen, die Ihr gerettet habt, zurück nach Sündensturz bringen.\n\nDenathrius' Machenschaften haben die Vorräte der Venthyr schwinden lassen und Prinz Renathal braucht alle Seelen, die er kriegen kann.", sourceObjective = "Bringt die aus dem Schlund geretteten Seelen zu Tenaval in Sündensturz in Revendreth.", completion = "Ah, Ihr wart also erfolgreich, wie ich erwartet habe.\n\nUnd jetzt werden wir diese Seelen für uns einsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62882] = { id = 62882, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regeln aufstellen", description = "Zurück, um mehr Seelen zu retten? Wie mutig.\n\nAllerdings muss ich sagen, dass Eure früheren Eskapaden die Aufmerksamkeit des Kerkermeisters erregt haben... und seinen Zorn. Schließlich konnte ihm bisher noch niemand entkommen.\n\nAbgesehen von mir.\n\nSeine Streitkräfte sind jetzt alarmiert und jagen alle irrenden Seelen, die der legendäre Schlundgänger vielleicht von ihm stehlen könnte.\n\nDie Situation ist für mich deswegen sehr... unpraktisch geworden. Wenn wir beide erfolgreich zusammenarbeiten wollen, müssen wir zuerst einige Grundregeln festlegen.\n\nUnd Ihr braucht die richtige Ausrüstung.", sourceObjective = "Legt Grundregeln für die Zusammenarbeit mit Ve'nari fest.", completion = "Kümmert Euch um diesen Seelenbewahrer. Ich möchte nicht noch einen beschaffen müssen.\n\nLos jetzt, an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[62883] = { id = 62883, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hüterin von hohem Ruhm", description = "So wie Euer Ruf in den Schattenlanden wächst, soll das Herz des Waldes mit Euch wachsen\n\nSucht Laurel, unsere Hüterin des Ruhms auf. Sie wird Euch mit der Magie vertraut machen, die wir unseren Jägern und Jägerinnen zuteilwerden lassen.", sourceObjective = "Sucht Laurel im Herz des Waldes auf.", completion = "<Laurel schlägt einen kleinen Tusch auf ihrer Harfe an, als Ihr näherkommt.>\n\nAh, unser neuer Champion und Gunstgefährte! Seid gegrüßt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[62884] = { id = 62884, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wald wird Euren Namen singen", description = "<Laurel zupft mit geschickten Fingern eine komplizierte Melodie und singt.>\n\nIch bin Hüterin von Wort und Tat,\nWeberin von Gesang und Lehren.\nSegen werden gewährt, gewinnt Ihr an Ruhm,\nund erfüllt die Eide, die wir ehren.\n\nSamenkörner der Stärke sind all Eure Taten\nund erblühen in sagenhafter Kraft.\nSprecht jetzt mit mir und seht, was bevorsteht,\nentdeckt, was unsere Magie erschafft!", sourceObjective = "Untersucht Eure Ruhmstufe beim Pakt der Nachtfae.", completion = "<Laurel spielt einen triumphierenden Tusch.>\n\nMöge Eure Geschichte wie Zweige wachsen, die in den Himmel ragen! So wie unsere Wurzeln tief in die Erde dringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[62886] = { id = 62886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ruf zur Hilfe", description = "Das Herz des Waldes benötigt Anima, um erneuert zu werden und zu wachsen.\n\nDie Wilde Jagd braucht Eure Hilfe, um die nötigen Dinge zu beschaffen. Zusammen sind wir stark.\n\nSprecht mit Blodwyn. Sie hilft immer da, wo es gerade am nötigsten ist.", sourceObjective = "Sprecht mit Blodwyn.", sourceObjectiveStatus = "unverified-source-field" }
quests[62890] = { id = 62890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Formerin des Waldes", description = "Ihr habt den Ruf gehört, <Schlundgänger/Schlundgängerin>, und unserem Wald wieder Ruhe gebracht.\n\nBleibt wachsam, denn es werden noch mehr Hilferufe folgen.\n\nEure gesammelte Anima wird dem Herz des Waldes gute Dienste leisten. Bringt sie zu Zayhad. Sie wird dafür sorgen, dass sie sicher ist, bis sie benötigt wird. Ihr findet sie tief zwischen den Wurzeln im Herz des Waldes.", sourceObjective = "Findet Zayhad zwischen den Wurzeln im Herz des Waldes.", completion = "Ohne Anima verkümmern die Wurzeln. Dank Eures Geschenks können wir alle wachsen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62891] = { id = 62891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir wartet", description = "Haine verkümmern und unsere Königin trauert auf unfruchtbarem Boden. Anima, kostbar wie Wasser, ist nun rar wie Schnee. Unsere Königin teilt ihre Habe und gewährt allen Unterschlupf unter Ihrem Geäst... aber ein einzelner Baum ist noch kein Wald.\n\nEuer Geschenk wird hoch geschätzt und behütet werden. Anima nährt unsere Wurzeln, so wie Hoffnung unsere Herzen. Der Ardenwald könnte noch einmal erblühen.", sourceObjective = "Lagert Anima in das Reservoir Eures Sanktums ein.", progress = "Nichts zu verschwenden, und auch nichts soll verschwendet werden. Sie wird hier sicher sein, bis sie gebraucht wird.", completion = "Der Wald wird Hungersnot und Dürre überdauern. Unsere Dankbarkeit lässt sich nicht beschreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[62892] = { id = 62892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Verlorenen", description = "Anima und Seelen. Wind und Regen. Der Ardenwald braucht beides, um zu gedeihen.\n\nSeelen, die für unser Geäst bestimmt waren, leiden in der Dunkelheit. Niemand entkommt dem Schlund... doch Ihr begebt Euch in seine Dunkelheit und kehrt zurück. Ihr seid die Erlösung.\n\nFlatterling kümmert sich mit Hingabe und Sorgfalt um die Schar. Sprecht mit ihr. Bringt unsere verlorenen Seelen heim.", sourceObjective = "Sprecht mit Flatterling im Herz des Waldes.", completion = "Bin ich froh, Euch zu sehen! Viele Seelen müssen gerettet werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[62893] = { id = 62893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vollbringt, was wir nicht können", description = "Gerüchten zufolge wart Ihr im Schlund und seid zurückgekehrt... und Ihr sollt Euch dort sogar mit einer Mittlerin angefreundet haben!\n\nUnzählige Seelen, die für den Ardenwald bestimmt waren, sind zu Unrecht in diesem dunklen Reich gefangen. Sie brauchen unsere Hilfe... und wir die ihre! Ohne sie können wir nicht die Magie des Herz des Waldes kultivieren.\n\nIch weiß, es ist viel verlangt... aber Ihr könntet unsere einzige Hoffnung sein, sie zu retten. Bitte reist in den Schlund und erreicht, was uns nicht möglich ist. Das Schicksal des Ardenwalds hängt davon ab!", sourceObjective = "Findet Ve'nari im Schlund.", completion = "So schnell zurück, Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[62894] = { id = 62894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück flattern", description = "Baine leidet in Torghast, aber zumindest wissen wir jetzt, dass er noch lebt.\n\nOhne einen Angriffsplan zu seiner Rettung zu eilen, wäre jedoch zum Scheitern verurteilt. Lasst mich etwas ausarbeiten.\n\nIn der Zwischenzeit könnt Ihr die Seelen, die Ihr gerettet habt, zurück zum Ardenwald bringen.\n\nNach den entsetzlichen Qualen im Schlund haben sie eine Ruhepause verdient, und sie werden den Anstrengungen der Nachtfae sicher von Nutzen sein.", sourceObjective = "Meldet Euch bei Flatterling im Herz des Waldes im Ardenwald.", completion = "Willkommen zurück! Ich bin froh, dass Ihr dort nicht gefangen wurdet! So war unsere ganze harte Arbeit nicht umsonst!\n\n<Flatterling kichert.>\n\nWir waren sehr fleißig!", sourceObjectiveStatus = "unverified-source-field" }
quests[62895] = { id = 62895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auswahl aufspüren" }
quests[62896] = { id = 62896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auswahl aufspüren" }
quests[62897] = { id = 62897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelen retten", description = "Oh, ich frage mich, welche Gestalt diese Seelen annehmen werden!\n\nWorte allein können nicht ausdrücken, wie dankbar wir sind, dass Ihr sie gerettet habt. Ihr habt nicht nur ihren Qualen ein Ende bereitet, sie werden vielleicht sogar dazu bereit sein, auch uns zu helfen.\n\nGeht, sprecht mit Zayhad. Sie waren schon lange nicht mehr in der Lage, sich um den Wald zu kümmern, aber das mag sich nun ändern. Das ist alles so aufregend!", sourceObjective = "Sprecht mit Zayhad.", completion = "Blätter im stürmischen Wind finden eine sichere Zuflucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62898] = { id = 62898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das erste neue Wachstum", description = "Lange haben wir geschlummert. Mit Seelen und Anima können wir wieder wachsen.\n\nWir müssen uns entscheiden. Wie wollen wir wachsen? Ihr dürft entscheiden, welche Blume zuerst erblüht.\n\nMit der Zeit wird der ganze Garten mithilfe von mehr Anima und helfenden Seelen wieder gedeihen. Im Moment signalisiert eine einzige Blüte Hoffnung für die Zukunft.\n\nLady Mondbeere wird Eure Wahl wissen wollen. Sucht sie auf, wenn Ihr soweit seid.", sourceObjective = "Beginnt eine Sanktumaufwertung.", completion = "Nun, Ihr wart fleißig. Ich glaube, wir befinden uns abermals in Eurer Schuld.\n\nIch denke, ich habe als Gegenleistung glücklicherweise genau das richtige Geschenk für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[62899] = { id = 62899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der endlose Wald", description = "Nun, mehr habe ich nicht für Euch! Hui! Ihr habt hier wahrlich alles abgearbeitet, was es an Aufgaben gab, nicht wahr? Die Wege auf und ab und sogar in den Schlund! In Eurem Kopf muss sich alles drehen.\n\n<Flatterling kichert.>\n\nIhr solltet Lady Mondbeere aufsuchen und ihr berichten, dass Euer Training abgeschlossen ist!\n\nSie wird Euch wahrscheinlich nicht das Gelernte abfragen.\n\nWahrscheinlich.", sourceObjective = "Kehrt zu Lady Mondbeere zurück.", completion = "Willkommen am Hof der Nacht, {name}. Ich weiß einfach, dass wir den Ardenwald retten werden! Oh, und den Rest der Schattenlande ebenfalls!\n\nUnd falls uns das misslingt und der Wald verdorrt und der Kerkermeister aus dem Schlund entflieht und die ewigen Reiche in niederschmetternde Verzweiflung stößt, aus der es keinerlei Entrinnen gibt...\n\nDann können wir sagen, dass wir zumindest unseren Spaß hatten, als wir es versucht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[62900] = { id = 62900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Medium für das Wachstum", description = "Während unser Band in sich selbst mächtig ist, könnt ihr es durch den Einsatz von Medien weiter stärken.\n\nMedien fokussieren die Anima zwischen Seelenbanden auf vielfältige Weise und erhöhen so unser beider Potenzial. Sie erlauben es uns, uns auf die einzigartigen Stärken des anderen abzustimmen.\n\nSetzen wir ein paar ein. Wenn sie unser Band weiter stärken, können sie uns helfen, den Wald zu schützen.", sourceObjective = "Fügt der Schmiede der Bande die Medien hinzu und setzt dann eins davon in einen freien Platz bei Niya ein.", progress = "Zusammen werden wir große Taten vollbringen.", completion = "Ihr werdet über die Zeit mit Niya zusammenwachsen, aber fürs Erste ist Euer Training beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62902] = { id = 62902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anima ist Macht", description = "Gute Arbeit, Boss. Wenn Ihr so weitermacht, dann überleben wir vielleicht dieses Chaos.\n\nBleibt aber wachsam. Solche Erfolgsnachrichten sprechen sich schnell herum und es wird nicht lange dauern, bis andere kommen und Euch um Hilfe bitten.\n\nDie ganze gesammelte Anima können wir hier gut gebrauchen. Bringt sie zu Vorarbeiter Plattfinger. Er wird alles sicher lagern.", sourceObjective = "Sprecht mit Vorarbeiter Plattfinger.", completion = "Der Boss kehrt als Sieger zurück! Habt Ihr Anima dabei?", sourceObjectiveStatus = "unverified-source-field" }
quests[62903] = { id = 62903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Reservoir wartet", description = "Anima ist in diesen Zeiten sehr knapp, und deswegen wurde ich mit der Verwaltung der Reserven beauftragt, bis sie gebraucht werden.\n\nLagert all Eure gesammelte Anima in diesem Reservoir hier ein. \nIch bürge für ihre Sicherheit.", sourceObjective = "Lagert Anima in das Reservoir Eures Sanktums ein.", progress = "Ich versichere Euch, das hier ist der sicherste Lagerplatz für Anima in ganz Revendreth.", completion = "So, geschafft! Die Anima ist nun sicher verwahrt.", sourceObjectiveStatus = "unverified-source-field" }
quests[62904] = { id = 62904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seele in Not", description = "Mit der Anima können wir vieles erreichen, aber dieses Sanktum kann nicht durch Anima alleine funktionieren. Um sein volles Potenzial zu entfalten, müssen viele Seelen zusammenarbeiten.\n\nDer Seelenwächter brennt darauf zu helfen, seit Ihr ihn aus dem Schlund gerettet habt. Eure einzigartige Fähigkeit, Seelen von dort zu retten, wird ihm sehr nützlich sein.\n\nWarum besucht Ihr ihn nicht mal?", sourceObjective = "Sprecht mit Tenaval.", sourceObjectiveStatus = "unverified-source-field" }
quests[62905] = { id = 62905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück in die Finsternis", description = "Immer mehr Seelen strömen in den Schlund und mit ihnen die Anima, die wir so dringend brauchen.\n\nIhr konntet mich aus diesem schrecklichen Ort befreien. Kann ich auf Euch zählen, Eure Stärke ein weiteres Mal einzusetzen?\nBitte bringt uns noch mehr gewogene Seelen, so dass wir die Macht unseres Sanktums weiter verstärken können.\n\nSucht Euch Hilfe und schafft das, was wir nicht schaffen können, Schlundgänger. Ihr seid unsere letzte und beste Hoffnung.", sourceObjective = "Findet Ve'nari im Schlund.", completion = "So schnell zurück, Schlundgänger?", sourceObjectiveStatus = "unverified-source-field" }
quests[62910] = { id = 62910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungleichgewicht der Kräfte", description = "Euer ewiger Feind, die Horde, wächst in den Schattenlanden in Stärke und Anzahl. \n\nWerdet Ihr und Eure Kameraden Euch ihrer Macht beugen? \n\nIch glaube nicht. Scheinbar kann nicht mal Euer Tod Euren Durst nach Schlachten stillen. \n\nWenn Ihr Eure Feinde entgegen aller Erwartungen niedermäht, werde ich Euch gebührend entlohnen.", sourceObjective = "Tötet in den Schattenlanden 25 Hordemitglieder der Stufe 60.", completion = "Gut gemacht, {class}! Sehr, sehr gut gemacht!", sourceObjectiveStatus = "unverified-source-field" }
quests[62914] = { id = 62914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koalition der Gewillten", description = "Die guten Leute in Revendreth leiden weiterhin unter der Unterdrückung durch die, die Denathrius loyal ergeben sind. Wir können uns erst offen gegen unseren einstigen Meister stellen, wenn unsere Streitkräfte wieder erstarkt sind.\n\nDie bereitwilligen Seelen, die Ihr aus dem Schlund gerettet habt, werden sich in diesen harten Zeiten als Segen erweisen.\n\nGeht zu Vorarbeiter Plattfinger. Er sucht nach Helfern, um Verbesserungen für unser Sanktum zu errichten. Zusammen werden wir dafür sorgen, dass Sündensturz sein volles Potenzial entfalten kann.", sourceObjective = "Sprecht mit Vorarbeiter Plattfinger.", completion = "Ah, was denn? Neue Seelen, oder?\n\nGut, sie haben auf jeden Fall Potenzial, das haben sie. Sie können mir hier bei einigen Sachen helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62915] = { id = 62915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hör mal, wer da hämmert", description = "Ich habe mir schon einige Sachen überlegt, wie wir diesen Ort hier aufwerten können, aber da Ihr die Anima gebracht habt, die uns dabei helfen wird, sollt Ihr auch entscheiden, was als erstes verbessert wird.\n\nAber lasst Euch nicht überwältigen. Je mehr Anima Ihr bringt, je mehr gewillte Seelen Ihr findet, desto mehr Möglichkeiten haben wir hier. Für jetzt reicht erstmal eine einzige Aufwertung.", sourceObjective = "Beginnt eine Sanktumaufwertung.", completion = "Gute Wahl. \n\nEs wird einige Zeit dauern, bis der Bau abgeschlossen ist, aber gut Ding will Weile haben, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[62916] = { id = 62916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer neuer bester Freund", description = "Ihr sucht einen neuen Freund? Huu-huu!\n\nViele Provosten sind gerne Freunde. Und <jetziger Freund/jetzige Freundin> kann Pause machen! Vielleicht zu den Klippen der Erholung gehen, Füße ausruhen, Kuchen essen...\n\n<Sika verliert sich in einem Tagtraum.>\n\nHuu! Stimmt!\n\nIch rufe Provosten. Ihr findet neue Freunde!", sourceObjective = "Wählt einen neuen Provostbegleiter und kehrt danach zu Sika zurück.", progress = "Neue Freunde, neue Freunde! Provosten lieben neue Freunde!", completion = "Huu-huu! Viel Spaß mit neuem Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[62917] = { id = 62917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteilte Seelen", description = "Die Macht der Ernter fließt durch Euren sterblichen Körper. Doch Ihr könntet über noch mehr Macht verfügen, wenn Ihr Eure Seele an eine andere bindet.\n\nDies birgt keine bekannten Risiken, sondern bietet viele Vorteile für beide beteiligten Seiten.\n\nDie Anklägerin wird den Vorgang überwachen. Trefft sie an der Schmiede der Bande, wenn Ihr bereit seid.", sourceObjective = "Trefft die Anklägerin in der Schmiede der Bande.", sourceObjectiveStatus = "unverified-source-field" }
quests[62918] = { id = 62918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindende Macht", description = "Die Macht der Ernter fließt durch Euren sterblichen Körper. Doch Ihr könntet über noch mehr Macht verfügen, wenn Ihr Eure Seele an eine andere bindet.\n\nDas Seelenband zu anderen ist nicht untrennbar. Aber dennoch sollte man diesen Schritt nicht leichtfertig wagen.\nIhr werdet die Vergangenheit Eures Partners sehen, seine Hoffnungen, Ängste, Träume und auch seine Erinnerungen, sofern noch welche vorhanden sind. Ihr seid dann im wahrsten Sinne des Wortes Seelenverwandte.\n\nIst das Band erst geknüpft, wächst Eure Verbindung über die körperliche Ebene hinaus und stärkt Euch in vielerlei Hinsicht... nicht nur Eure Muskeln.", sourceObjective = "Schließt das Ritual der Seelenbindung ab.", completion = "Ihr habt bisher ein... interessantes Leben geführt. Ich werde mich bemühen, es noch interessanter zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62919] = { id = 62919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stärkung des Bands", description = "Spürt Ihr es auch? Unsere Verbindung ist stärker, als ich es für möglich gehalten hätte.\n\nMir wurde gesagt, das Band werde mit der Zeit noch enger, aber dass wir auch die Möglichkeit hätten, diesen Prozess zu beschleunigen.\n\nSündensturz braucht unsere Stärke. Vielleicht ist es das Beste, wenn wir diese Methode jetzt zur Anwendung bringen.", sourceObjective = "Benutzt die Schmiede der Bande, um Euer Band mit Nadjia zu stärken.\n\nTut dies, indem Ihr eine Macht auswählt und sie aktiviert.", progress = "Dies wird uns beiden Nutzen bringen.", completion = "Gemeinsam werden wir viel erreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62920] = { id = 62920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Medium für die Veränderung", description = "Die Macht Eures Bandes ist außerordentlich, kann aber durch den Einsatz von Medien noch weiter gestärkt werden.\n\nMedien fokussieren die Energie Eures Seelenbands direkter und erhöhen so Euer Potenzial auf vielfältige Art und Weise.\n\nNutzt die, die ich Euch gegeben habe, um diese Macht zu testen, aber keine Angst... Ihr werdet weitere auf Eurer Reise finden.", sourceObjective = "Fügt der Schmiede der Bande die Medien hinzu und setzt dann eins davon in einen freien Platz bei Nadjia Nebelklinge ein.", progress = "Dieser Schritt ist entscheidend für Euer Voranschreiten.", completion = "Euer Seelenband wird mit der Zeit wachsen, aber fürs Erste ist Euer Training beendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[62921] = { id = 62921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere wahre Vorsehung", description = "Wir sind dankbar für diese Partnerschaft, <Schlundgänger/Schlundgängerin>.\n\nMit Eurer Hilfe wird Renathal uns in ein neues Zeitalter führen, in dem Revendreth wieder seiner wahren Vorsehung entsprechen kann.\n\nKehrt jetzt zu ihm zurück, damit die wahre Arbeit beginnen kann.", sourceObjective = "Kehrt zu Prinz Renathal zurück.", completion = "Ich hoffe, Ihr habt alles zu Eurer Zufriedenheit vorgefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[62928] = { id = 62928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Ring des Schutzes", description = "<Ihr habt den Bauplan für einen defensiven Zauberschutz gefunden, der Euren Seelenbanden einen Vorteil auf dem Pfad des Aufstiegs schenken könnte.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Ring des Schutzes zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62932] = { id = 62932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erkundet Torghast", description = "Baine ist in Sicherheit, aber unsere anderen Verbündeten sind immer noch Gefangene des Kerkermeisters und damit in großer Gefahr.\n\nTorghast ist ein sich ständig verändernder Ort und seine Gestalt wechselt nach dem Willen des Meisters. Es könnte unmöglich sein, sie mit normalen Mitteln zu finden.\n\nGeht erst einmal zu den Gefängniszellen, um Informationen zu finden. Sucht nach Hinweisen auf unsere vermissten Freunde und bringt sie mir dann.", sourceObjective = "Sucht in Torghast nach Hinweisen auf Eure Verbündeten.", progress = "Was habt Ihr herausgefunden?", completion = "<Bolvar sieht sich das Objekt genau an.>\n\nIch spüre eine Vertrautheit. Der Besitzer des Schlüssels könnte in die Gefangennahme von Jaina Prachtmeer verwickelt sein.\n\nIch benötige noch etwas mehr Zeit, um weiter zu forschen. Ich werde Euch kontaktieren, wenn ich unsere nächsten Schritte beschlossen habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62935] = { id = 62935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überreste der Hoffnung", description = "Ich habe den Schlüssel untersucht, den Ihr aus Torghast zurückgebracht habt, {name}.\n\nEr ist die Bestätigung, dass Jaina Prachtmeer immer noch irgendwo in dem Turm gefangen gehalten wird. Aber wir wissen nicht, wo genau.\n\nAn diesem verfluchten Ort werden unzählige Seelen gefangen gehalten. Ein paar wenige könnten noch intakt sein, aber viele von ihnen sind zersplittert und zerbrochen.\n\nLasst Gnade mit den Überresten walten und befreit jene, wo es noch möglich ist. Vielleicht können sie Euch bei der Suche helfen.", sourceObjective = "Ergattert neue Informationen von den gefangenen Seelenrückständen in Torghast.", completion = "Es ist gut, dass Ihr diese gequälten Seelen befreien konntet, {name}. Und es ist schade, dass keine von ihnen uns helfen konnte.\n\nIch muss über unsere weitere Vorgehensweise nachdenken. Ich lasse Euch wissen, wenn ich diesbezüglich eine Entscheidung gefällt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[62938] = { id = 62938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Preis der Information", description = "Wir müssen unsere Suche nach Jaina Prachtmeer fortsetzen. Ich möchte eine neue Strategie vorschlagen.\n\nSeit meiner Ankunft in Oribos sind viele Mittler auf mich zugekommen. Einige stellten Fragen, andere boten Hilfe an, wenn auch gegen einen Preis.\n\nIhr habt andere von ihnen in Torghast getroffen. Sie verfügen vielleicht über Informationen, die uns nutzen könnten, obschon ich bezweifle, dass sie uns diese uneigennützig überlassen.\n\nSucht sie auf und reizt ihre Habsucht. Bietet ihnen an, für jegliche Form an Information zu bezahlen.", sourceObjective = "Befragt die in Torghast gefangenen Mittler.", progress = "Eine vielversprechende Spur.", completion = "Die Habsucht der Mittler scheint von Nutzen gewesen zu sein.\n\nIhr könntet genau das gefunden haben, was wir benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62951] = { id = 62951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Kleia", description = "Artemede hat Kleia persönlich trainiert und sie durch die Kampfmeditation und Übungen gepeitscht.\n\nSie ist weit gekommen und ist bereit für eine weitere Prüfung auf dem Pfad des Aufstiegs.\n\nKehrt ins Kolosseum zurück und beratet sie in Taktikfragen, so dass sie den Sieg erringt.", sourceObjective = "Besteht eine Prüfung des Pfads des Aufstiegs mit Kleia.", completion = "Wie wir erwartet haben. Kleias Stärke wächst und wächst.", sourceObjectiveStatus = "unverified-source-field" }
quests[62952] = { id = 62952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Pelagos", description = "Harter Kampf ist nicht seine Stärke, aber Pelagos las, meditierte und trainierte, um besser auf dem Pfad zu werden.\n\nWir glauben, er ist bereit, den Sieg zu suchen.\n\nEr hat Euch als strategischen Beistand angefordert. Mit der Hilfe seiner Freunde ist er stärker.", sourceObjective = "Besteht eine Prüfung des Pfads des Aufstiegs mit Pelagos.", completion = "Eines Tages wird Pelagos seine Herausforderungen alleine meistern müssen, um zu wachsen.\n\nAber jetzt ist die Unterstützung seiner Seelenbande alles, was er braucht.", sourceObjectiveStatus = "unverified-source-field" }
quests[62953] = { id = 62953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Mikanikos", description = "Mikanikos hat hart in der Ewigen Schmiede gearbeitet, Bron kalibriert und seine Kampfroutinen verfeinert.\n\nEr vertraut auf seine jüngsten Änderungen und bittet darum, erneut eine Prüfung ablegen zu dürfen.\n\nBetretet den Pfad mit Mikanikos, so dass er die Stärken und Schwächen seines Goliaths austesten kann.", sourceObjective = "Besteht eine Prüfung des Pfads des Aufstiegs mit Mikanikos.", completion = "Bron ist offensichtlich viel stärker geworden!\n\nIch freue mich schon darauf zu sehen, wie Mikanikos dieses neue Wissen nutzt, um die Zenturionen zu verbessern.", sourceObjectiveStatus = "unverified-source-field" }
quests[62954] = { id = 62954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Kalisthene", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Kalisthene. Sie sollen die Lektionen lernen, die ihre Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Kalisthene zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Kalisthene auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[62966] = { id = 62966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Zeugen finden", description = "Ihr habt zwei unserer Verbündeten aus Torghast gerettet, aber Anduin und Thrall fehlen noch.\n\nDie Gänge dieses Turms sind weitläufig... scheinbar endlos. Man könnte eine Ewigkeit damit zubringen, durch diese unheiligen Hallen zu wandern.\n\nAuf Euren Expeditionen seid Ihr vielen unglückseligen Gefangenen begegnet. Vielleicht hat einer von ihnen etwas gesehen oder gehört, das unserer Suche weiterhelfen könnte.\n\nSucht alle Gefangenen auf, die über die von uns benötigten Informationen verfügen könnten, {name}.", sourceObjective = "Sucht in Torghast nach einem Gefangenen, der etwas darüber wissen könnte, wo Anduin oder Thrall gefangen gehalten werden.", completion = "Ich finde es sehr ermutigend, dass Thrall noch lebt. Beim Licht, wir werden ihn finden.\n\nIch fürchte allerdings um Anduin. Die Dunkelheit hungert nach seiner Seele.\n\nWir müssen uns bereit machen. Ihr werdet von mir hören, wenn es Zeit ist, weiterzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62967] = { id = 62967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängnis der Vergessenen", description = "Der Wächter, den Ihr im Turm getötet habt, hatte einen interessanten Gegenstand bei sich. \n\nFragt lieber nicht, warum ich weiß, was Ihr wo im Turm gemacht habt. Ich habe meine Quellen.\n\nDieser Schlüssel könnte zu etwas Interessantem in Torghast führen... oder zu etwas Schrecklichem. Wahrscheinlich zu etwas Schrecklichem.\n\nForscht weiter und findet heraus, was er aufschließt.", sourceObjective = "Findet heraus, welche Funktion der Schlüssel der Vergessenen hat.\n\nBereitgestellter Gegenstand:", completion = "<Als Ihr den Schlüssel in das Gerät einsetzt, zittert es kurz und öffnet sich dann.>", sourceObjectiveStatus = "unverified-source-field" }
quests[62969] = { id = 62969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Damit die Spur nicht kalt wird", description = "Nach dem, was der gefangene Gräber Euch erzählt hat, scheint Thrall tief nach Torghast hineingebracht worden zu sein. Die Qualen, die er erduldet, müssen unvorstellbar sein.\n\nWir müssen erfahren, wo er festgehalten wird, bevor die Spur erkaltet.\n\nDer Turm ist weitläufig und gefährlich. Sucht dort, wo es Euch möglich ist, und bringt alle Hinweise mit, die Ihr findet.\n\nSeid auf der Hut, {name}. Der Kerkermeister hat Euch im Auge.", sourceObjective = "Betretet Torghast und findet etwas, das uns hilft, Thrall aufzuspüren.", progress = "Habt Ihr schon etwas gefunden, das uns hilft, Thrall aufzuspüren?", completion = "<Bolvar mustert das Totem.>\n\nJa, das könnte uns den Weg zu Thralls Aufenthaltsort weisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62970] = { id = 62970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Provostpostbeutel", description = "<Ihr habt den Bauplan für einen Beutel in Provostgröße gefunden, perfekt für Briefe.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Provostpostbeutel zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62971] = { id = 62971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Vergoldeter Abakus", description = "<Ihr habt den Bauplan für einen Abakus in Provostgröße gefunden, mit dem man Einzahlungen und Abhebungen über große Distanzen berechnen kann.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Vergoldeter Abakus zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62976] = { id = 62976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerkszeuggürtel", description = "<Der Handwerkszeuggürtel hat viele Taschen und Schlaufen und enthält viele Werkzeuge und Materialien.\n\nEr wird Euren Provosten nicht nur befähigen, Euch bei Aufgaben der Handwerkskunst zu helfen, sondern auch Handwerkswaren zu tragen.>", sourceObjective = "Ruft Euren Provostbegleiter mit 'Provost beschwören' und übergebt den Handwerkszeuggürtel.\n\nBereitgestellter Gegenstand:", completion = "Werkzeug für mich? Toll! Mache gern Dinge.\n\nFreue mich drauf, mehr zusammenzuarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[62981] = { id = 62981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Handwerkszeuggürtel", description = "<Ihr habt einen Bauplan für einen gut verarbeiteten Werkzeuggürtel gefunden, ein perfektes Geschenk für Euren Lieblingsprovost.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Handwerkszeuggürtel zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62984] = { id = 62984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Medaillon des Dienstes", description = "<Ihr habt den Bauplan zur Herstellung eines Medaillons des Dienstes gefunden, dem angesehenen kyrianischen Symbol der Belobigung. Indem Ihr Eurem Sanktum Materialien spendet, könnt Ihr Medaillons erhalten, um den Pfad betreten zu können.\n\nDactylis sollte Euch dabei behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Medaillon des Dienstes zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr die Materiallisten für ein Medaillon des Dienstes gefunden. Ich freue mich schon darauf, Euch in Zukunft für Eure Beiträge zu belohnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[62985] = { id = 62985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Aussehen ausgraben", description = "Wenn Ihr Euch an der Schlammlache umseht, findet Ihr gewiss einen Rüstungsfarbstoff. Es wäre schön, die Möglichkeit zu haben, meinen Gürtel umzufärben.", sourceObjective = "Durchsucht Gegner oder weggeworfene Flaschen im Gräberwald nach einem Rüstungsfarbstoff.", progress = "Habt Ihr einen gefunden?", completion = "Wir Gräber sind ein wandlungsfähiges Völkchen. Wenn Ihr andere Farbstoffe auftreibt, haben wir Auswahlmöglichkeiten, meinen Gürtel oder sogar ein Wams zu färben, wenn Ihr eins findet. Außerdem sind wir gut in der Follikelkontrolle; wenn Ihr also Plakate von gut aussehenden Leuten findet, gebt sie mir, und ich werde lernen, wie ich meine passend wachsen lassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[62986] = { id = 62986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Vesperglocke der Anrufung", description = "<Ihr habt einen Bauplan für eine einmalig benutzbare Glocke entdeckt, die den Kurier Hermestes überall in den Schattenlanden herbeirufen kann.\n\nDactylis sollte Euch bei ihrer Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Vesperglocke der Anrufung zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62993] = { id = 62993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rätsel des Todes" }
quests[62995] = { id = 62995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geistgeschmiedete Aegis", description = "<Als Ihr den Schild aufhebt, scheinen Eure Hände leicht von ihm abgestoßen zu werden.\n\nDies sollte Euren Seelenbanden helfen, auf dem Pfad des Aufstiegs ein paar Schläge einzustecken.>", sourceObjective = "Bringt die geistgeschmiedete Aegis zu Paolone.", completion = "Schild? Ja! Fein! Bewahre ich auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[62996] = { id = 62996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phiole voll Lichfrost", description = "<Die mit einer eisigen Flüssigkeit gefüllte Phiole fühlt sich kalt an.\n\nDies sollte die Gegner Eurer Seelenbande auf dem Pfad des Aufstiegs behindern.>", sourceObjective = "Bringt die Phiole voll Lichfrost zu Paolone.", completion = "Seltsame Flüssigkeit... Toll! Kalt! Bewahre ich auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[62997] = { id = 62997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Phiole voll Lichfrost", description = "<Ihr habt einen Bauplan für ein Gebräu entdeckt, das Gegner auf dem Pfad des Aufstiegs einfrieren kann.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Phiole voll Lichfrost zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[62998] = { id = 62998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ring des Schutzes", description = "<Ihr legt den Ring ab und werdet von einer schützenden Blase zurückgestoßen.\n\nDies sollte die Gegner Eurer Seelenbande aus einem Bereich auf dem Pfad des Aufstiegs vertreiben.>", sourceObjective = "Bringt den Ring des Schutzes zu Paolone.", completion = "Ring? Toll! Sehr schön! Bewahre ich auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[62999] = { id = 62999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Croman", sourceObjective = "Auch wenn es nicht blutet, können wir es trotzdem töten!", sourceObjectiveStatus = "unverified-source-field" }
quests[63000] = { id = 63000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bauplan: Amulett des Fokus", description = "<Ihr habt den Bauplan für ein Amulett gefunden, das Eure Seelenbande auf dem Pfad des Aufstiegs mit Energie erfüllen könnte.\n\nDactylis sollte Euch bei seiner Herstellung behilflich sein können.>", sourceObjective = "Bringt den Bauplan: Amulett des Fokus zu Dactylis.\n\nBereitgestellter Gegenstand:", completion = "Wie ich sehe, habt Ihr einen neuen Bauplan beschafft. Ich freue mich darauf, Euch bei der Herstellung behilflich zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63002] = { id = 63002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allein ist es gefährlich", description = "Ich gehe davon aus, dass Ihr alles, was die Elysische Feste zu bieten hat, gut kennt, aber das allein wird nicht ausreichen, um Denathrius zu bezwingen.\n\nIhr braucht ein Seelenband, <Schlundgänger/Schlundgängerin>, das Euch unterstützt.\n\nSucht Seelenführerin Daelia in der Kammer unter uns auf. Sie hat das Ritual vorbereitet.", sourceObjective = "Sprecht mit Seelenführerin Daelia im Sanktum der Bindung.", completion = "Ich sehe schon jetzt, dass Eure Seele heller brennt als die der meisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63003] = { id = 63003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteilte Seele", description = "Ihr seid mit Konflikten so gut wie jeder andere Soldat in Maldraxxus vertraut, <Schlundgänger/Schlundgängerin>. Aber wir kämpfen nicht allein.\n\nEs ist sehr weise, sich auf die Stärken Eurer Verbündeten zu stützen. So macht man das in Maldraxxus.\n\nSprecht mit Seuchenerfinder Marileth. Er wird Euch zeigen, wie man eine Seelenbindung eingeht und ihre Vorteile am besten nutzt.", sourceObjective = "Sprecht mit Seuchenerfinder Marileth über den Prozess der Seelenbindung.", completion = "Ich bin so froh, Euch wiederzusehen, mein Lehrling!", sourceObjectiveStatus = "unverified-source-field" }
quests[63006] = { id = 63006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Königin und Hain!", description = "Ihr habt bereits so viel getan, um uns zu helfen, seit Ihr unser Reich betreten habt! Ich bin so froh, dass Ihr Euch dazu entschieden habt, Euch unserem Pakt anzuschließen.\n\nJedoch wird sicherlich später noch genug Zeit bleiben, um in Erinnerungen zu schwelgen. Ihr seid zu einer Audienz bei der Winterkönigin persönlich eingeladen!\n\nLassen wir sie nicht warten!", sourceObjective = "Schließt Euch dem Pakt der Nachtfae an.", completion = "Eure Taten werden selbst durch den Schleier hindurch spürbar sein. Helft dem Wald, dann besteht auch Hoffnung für alle sterblichen Welten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63008] = { id = 63008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schmiede der Bande", description = "Um dem Hof und dem Wald am besten zu dienen, müsst Ihr mit einer weiteren Fae eine Bindung vollziehen.\n\nEs ist ein uraltes Ritual, das Euch für die bevorstehenden Prüfungen große Macht verleiht.\n\nFlatterling wird Euch weiter führen.", sourceObjective = "Trefft Euch mit Flatterling in der Schmiede der Bande.", completion = "Oh, wow! Ich helfe anderen immer furchtbar gern bei ihrer Seelenbindung! Das ist meine Lieblingsaufgabe!", sourceObjectiveStatus = "unverified-source-field" }
quests[63022] = { id = 63022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Addendum zu Regel 6: Rettet mich um jeden Preis", description = "Ihr! Ihr da! Wartet!\n\nIhr seid <der berüchtigte Schlundgänger/die berüchtigte Schlundgängerin>, nicht wahr? Ich habe schon viel von Euch gehört.\n\nBitte helft mir! Die Schlundgebundenen haben meinen Gefährten die Essenz geraubt, um damit ihre schändlichen Runen zu erschaffen.\n\nEiner von ihnen hat mich hier gebunden. Bestimmt bin ich sein nächstes Opfer. Ihr müsst ihn töten, um mich zu befreien!\n\nSelbstverständlich werde ich Euch dafür entschädigen. Ich habe während meiner Zeit im Schlund eine beträchtliche Menge Stygia gesammelt. Rettet mich, und es gehört Euch!", sourceObjective = "Tötet Runenmeister Mavrok.", progress = "Wir haben keine Zeit zu verlieren. Beeilt Euch, bevor die Schlundgebundenen zurückkehren!", completion = "Gerade noch rechtzeitig! Diese Scheusale wollten mich gleich niedermachen.\n\nHier, wie vereinbart Eure Bezahlung in Stygia.\n\nEhrlich gesagt, schulde ich Euch noch viel mehr als das hier. Aber ich habe nichts weiter anzubieten... außer weisen Ratschlägen und Warnungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63029] = { id = 63029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Hochlords", description = "Hochlord Fordragon hat verlauten lassen, dass Ihr sofort zurück zu ihm nach Oribos kommen sollt.\n\nIch weiß nur, dass dies etwas mit dem Schlund zu tun hat.\n\nIhr solltet ihn umgehend aufsuchen. Alles, was mit diesem dunklen Ort zu tun hat, sollte höchste Priorität für uns haben.", sourceObjective = "Meldet Euch bei Hochlord Bolvar Fordragon in Oribos.", completion = "Ich habe bedauerliche Neuigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63030] = { id = 63030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Hochlords", description = "Hochlord Fordragon will Euch unverzüglich in Oribos sehen!\n\nIch kenne keine Details, aber der Bote erwähnte den Schlund.\n\nIhr solltet so schnell wie möglich zu ihm gehen. Wenn es mit dem Schlund zu tun hat, muss es etwas Ernstes sein!", sourceObjective = "Meldet Euch bei Hochlord Bolvar Fordragon in Oribos.", completion = "Ich habe bedauerliche Neuigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63031] = { id = 63031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffung: Kristallisierte Stygia", description = "<Dieser Kristallsplitter scheint aus einer der riesigen Kristallstrukturen in der Gegend herausgebrochen worden zu sein. Er vibriert voller ungenutzter Energie.\n\nVe'nari hätte wahrscheinlich ein Interesse an allen solchen Splittern, die Ihr finden könnt.>", sourceObjective = "Sammelt 10 kristallisierte Stygia und bringt sie zu Ve'nari im Schlund.", progress = "Was habt Ihr zusammengetragen, {class}?", completion = "Ah, ja, die inaktive Stygia im Schlund nimmt manchmal diese Form an.\n\nEs war gut, dass Ihr sie mir gebracht habt, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63032] = { id = 63032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Hochlords", description = "Hochlord Fordragon erwartet Euch in Oribos.\n\nWir wissen nur, dass es etwas mit dem Schlund zu tun hat.\n\nBegebt Euch zu ihm und zeigt ihm, dass die Maldraxxi niemals zögern. Nicht einmal im Angesicht eines solch dunklen Orts.", sourceObjective = "Meldet Euch bei Hochlord Bolvar Fordragon in Oribos.", completion = "Ich habe bedauerliche Neuigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63033] = { id = 63033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Hochlords", description = "Ein Bote aus Oribos hat uns ausgerichtet, dass Hochlord Fordragon Euch in Oribos sehen will.\n\nEs scheint sich um den Schlund zu handeln... und zweifelsohne die Pläne des Meisters.\n\nIhr solltet seinem Ruf folgen, <Schlundgänger/Schlundgängerin>. Wir dürfen nichts dem Zufall überlassen.", sourceObjective = "Meldet Euch bei Hochlord Bolvar Fordragon in Oribos.", completion = "Ich habe bedauerliche Neuigkeiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[63034] = { id = 63034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elysischen Felder", description = "Reist zur Bastion, dem ewigen Zuhause der geflügelten Kyrianer.\n\nLasst Euch nicht von Ihren goldenen Feldern und glänzenden Türmen täuschen... die große Animadürre hat die Kyrianer geschwächt und an den Rand eines Bürgerkriegs mit ihren eigenen gefallenen Brüdern gedrängt.\n\nEure Unterstützung wird von großem Nutzen für sie sein. Sucht in Eurem neuen Sanktum, der Elysischen Feste, nach der, die Kalisthene genannt wird. Sie kann Euch weiterhelfen.\n\nPfadschreiber Roh-Avonavi im Ring der Übertragung wird für Euren Transport sorgen.", sourceObjective = "Sprecht mit Kalisthene bei der Elysischen Feste in der Bastion.", completion = "Warum seid Ihr in unser Reich gekommen, Sterblicher?", sourceObjectiveStatus = "unverified-source-field" }
quests[63035] = { id = 63035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine frische Klinge", description = "Obwohl sie einst vereint die Schattenlande verteidigt haben, liegen die Häuser von Maldraxxus jetzt im Zwist miteinander.\n\nIn ihrem Reich prallen die Armeen aufeinander, selbst die Bastion bleibt nicht verschont. Nur noch die Nekrolords halten dem Primus die Treue.\n\nSprecht mit Secutor Mevix am Sitz des Primus in Maldraxxus. Mit seinem strategischen Gespür wird er Euch dorthin senden, wo Ihr am meisten gebraucht werdet.\n\nPfadschreiber Roh-Avonavi im Ring der Übertragung kann für Euren Transport sorgen.", sourceObjective = "Sprecht mit Secutor Mevix im Sitz des Primus in Maldraxxus.", completion = "Ah, eine weitere Klinge an unserer Seite! Und Ihr seid noch nicht einmal tot!", sourceObjectiveStatus = "unverified-source-field" }
quests[63036] = { id = 63036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiederherstellung des Gleichgewichts", description = "Der Ardenwald ist für den Wiedergeburtszyklus der Nachtgeister, die ihr Reich betreten, von großer Wichtigkeit.\n\nLeider führte die Animadürre zum Verlust ganzer Haine – diese Seelen werden ihren Zyklus nie vollenden.\n\nJetzt wollen die Feinde auch noch den Rest des einst ruhigen Walds zerstören, sie bedrohen den bereits in Mitleidenschaft gezogenen Hof der Nacht. \n\nLady Mondbeere vom Hof bittet um Hilfe. Pfadschreiber Roh-Avonavi im Ring der Übertragung wird für Euren Transport sorgen.", sourceObjective = "Sprecht mit Lady Mondbeere beim Herz des Waldes im Ardenwald.", completion = "Willkommen! Was führt Euch ins Herz des Waldes?", sourceObjectiveStatus = "unverified-source-field" }
quests[63037] = { id = 63037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Düstere Ambitionen", description = "Prinz Renathal wagt eine kühne Rebellion gegen seinen Vater, den ruchlosen Grafen Denatharius, der uns alle betrog, indem er Revendreths reiche Animavorräte in den Schlund schüttete.\n\nIhr müsst nach Revendreth reisen, um Renathal bei seinen Bemühungen zu unterstützen. Er ist unsere größte Hoffnung, um die Ordnung in Revendreth wiederherzustellen.\n\nPfadschreiber Roh-Avonavi im Ring der Übertragung wird für Euren Transport sorgen.", sourceObjective = "Sprecht mit Prinz Renathal in Sündensturz in Revendreth.", completion = "Was verschafft mir das Vergnügen eines Sterblichen, der Revendreth zu solch... ungelegener Zeit besucht?", sourceObjectiveStatus = "unverified-source-field" }
quests[63038] = { id = 63038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung mit Garantie", description = "<Der Mittler scheint vom Kartell Ve zu sein. Vielleicht war er einst Partner von Ve'nari.\n\nSeine Hand umklammert eine Liste von Gegenständen und eine Eindämmungskugel.\n\nWenn Ihr die Aufgabe dieses Mittlers erledigt und die Gegenstände an Ve'nari zurückschickt, werdet Ihr sicher eine Entschädigung erhalten.>", sourceObjective = "Benutzt die Eindämmungskugel, um 8 eingeschlossene Essenzen zu Ve'nari zu schicken.\n\nEmpfohlene Spieleranzahl [3]", completion = "Ausgezeichnet, {name}. Ich hatte mich schon gefragt, was aus diesem Mitarbeiter geworden ist.\n\nEs freut mich zu wissen, dass sein Ableben kein vollständiger Verlust war.", sourceObjectiveStatus = "unverified-source-field" }
quests[63039] = { id = 63039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Monument der Vergeltung", description = "<Der Tiegel der Verdammten ist übersät mit Leichen von Rittern der Schwarzen Klinge, was die Folgen Eures ersten Vorstoßes an diesen trostlosen Ort verdeutlicht.\n\nIhr Opfer sollte nicht vergessen werden.>", sourceObjective = "Sammelt 8 Schwarzrunenklingen und errichtet ein Monument für die Opfer der Schwarzen Klinge im Tiegel der Verdammten.", progress = "<Diese Klippe ist im gesamten Schlund gut sichtbar.\n\nDer Bau des Monuments an dieser Stelle wird sicherlich den Zorn des Kerkermeisters erregen.>", completion = "<Das Monument strahlt die Energie der Runenklingen der gefallenen Ritter aus.\n\nEs ist ein kleines Denkmal an die gebrachten Opfer, aber es wird reichen müssen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[63040] = { id = 63040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zustellung mit Garantie", description = "<Der Mittler scheint vom Kartell Ve zu sein. Vielleicht war er einst Partner von Ve'nari.\n\nSeine Hand umklammert eine Liste von Gegenständen und eine Eindämmungskugel.\n\nWenn Ihr die Aufgabe dieses Mittlers erledigt und die Gegenstände an Ve'nari zurückschickt, werdet Ihr sicher eine Entschädigung erhalten.>", sourceObjective = "Benutzt die Eindämmungskugel, um 5 Schriftrollen der Unterwerfung und 3 Fesselwerkzeuge an Ve'nari zu schicken.\n\nEmpfohlene Spieleranzahl [3]", completion = "Ausgezeichnet, {name}. Ich hatte mich schon gefragt, was aus diesem Mitarbeiter geworden ist.\n\nEs freut mich zu wissen, dass sein Ableben kein vollständiger Verlust war.", sourceObjectiveStatus = "unverified-source-field" }
quests[63041] = { id = 63041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belohnungen sind knapp" }
quests[63043] = { id = 63043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissene Seelen", description = "Die Fallen... sie konnten uns bisher nichts anhaben. Zu viele Seelen... entkommen.\n\nSie... haben neue Fallen gebaut... zerreißen fliehende Seelen...\n\n...zu spät für mich. Zerstören... damit andere vielleicht fliehen können!", sourceObjective = "Zerstört 10 Seelenzerfetzungsfallen im Tremaculum.", sourceObjectiveStatus = "unverified-source-field" }
quests[63044] = { id = 63044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rattenschwärmer" }
quests[63045] = { id = 63045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seele nähren", description = "Sie... haben mir meine Anima geraubt... für ihr Ritual...\n\nMächtige Seelen bringen sie hierher... zu diesem Altar... und opfern sie, um unaussprechliche Schrecken im Dienst des Kerkermeisters herbeizurufen.\n\nEinst war ich sehr mächtig... Erfüllt mich mit der Anima, die sie gestohlen haben... dann kehrt meine Macht zurück.\n\nUnd dann, zusammen... werden wir ihren Anführer vernichten.", sourceObjective = "Holt die gestohlene Anima zurück, um die rachsüchtige Seele zu ermächtigen und mit ihrer Hilfe Inquisitor Moorlack zu besiegen.\n\nEmpfohlene Spieleranzahl [3]", completion = "Was für eine Geschichte, {name}. Fast nichts motiviert Körper und Geist so sehr wie Rache.", sourceObjectiveStatus = "unverified-source-field" }
quests[63046] = { id = 63046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende und der Anfang", description = "Ich bin so froh, dass Ihr unsere Verbindung zum Konservatorium der Königin wiederhergestellt habt!\n\nAngesichts dieser Errungenschaft hat die Winterkönigin darum gebeten, dass Ihr ihr im Hain des Erwachens Eure Aufwartung macht!\n\nIhr werdet aus erster Hand den Zweck des Ardenwalds erfahren und ein größeres Verständnis für unsere heilige Aufgabe erlangen, bevor auch Ihr diese auf Euch nehmt.\n\nSputet Euch! Lasst nicht alle warten!", sourceObjective = "Erfahrt mehr über Wildsamen von der Winterkönigin.", completion = "Willkommen. Gemeinsam werden wir gedeihen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63047] = { id = 63047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffung: Runengeschmiedete Fesseln", description = "<In die Ketten hier sind Herrschaftsrunen geschnitzt, die ihnen die nötige Magie verleihen, um die Mächtigsten unter den Gefangenen der Schlundgebundenen zu bändigen.\n\nZweifellos könnte die Untersuchung dieser Runen für Ve'nari von einem gewissen Nutzen sein.>", sourceObjective = "Sammelt 9 runengeschmiedete Fesseln und bringt sie zu Ve'nari im Schlund.", progress = "Noch eine Transaktion?", completion = "Ketten? Die sind hier nicht gerade schwer zu finden... Wartet, diese Runen...\n\nIhr habt in der Tat ein scharfes Auge. Die Magie hier ist es wert, weiter untersucht zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63050] = { id = 63050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffung: Lodernde Barren", description = "<Die Runenschmiede haben diesen Barren mit einem Zauber durchdrungen, der ihn mit unauslöschlichen Flammen brennen lässt.\n\nWahrscheinlich wird dieses Metall dazu verwendet, um die schlundgebundenen Beschützer von Zovaals Kessel zu ermächtigen.\n\nEin paar Proben dieses Erzes Ve'nari zu bringen, könnte sie bei ihren Versuchen unterstützen, die Geheimnisse des Kerkermeisters zu entschlüsseln.>", sourceObjective = "Sammelt 12 lodernde Barren und bringt sie zu Ve'nari im Schlund.", progress = "Was ist das?", completion = "Faszinierend. Ich habe mich oft gefragt, was die Beschützer des Kessels von den übrigen Schlundgebundenen unterscheidet.\n\nIch hoffe, die Beschaffung hat Euch nicht vor allzu große Schwierigkeiten gestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63051] = { id = 63051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mangelndes Vertrauen", description = "Ah, <Schlundgänger/Schlundgängerin>! Ich möchte mich vorstellen. Ich bin Ve'rayn und ich kümmere mich um Vermögenswerte und Verpflichtungen, die Aktiva und Passiva, des Kartells Ve.\n\nIch habe schon gehört, dass Ihr Euch frei zwischen Oribos und dem Schlund bewegen könnt. An letztgenanntem Ort hat mein Kartell großes Interesse.\n\nKönnte ich Euch wohl ein paar Fragen dazu stellen?\n\nFür Eure Zeit und Informationen werdet Ihr natürlich gebührend entschädigt, denn dies sind bedeutende Güter.", sourceObjective = "Beantwortet Ve'rayns Fragen zum Schlund.", completion = "Das Kartell Ve hat Euch Fragen über mich gestellt?\n\nIch fühle mich geschmeichelt. Erzählt ihnen kein Wort über mich.\n\nNiemals.\n\nUnd jetzt kommt. Auf uns wartet noch Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63052] = { id = 63052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauensschritt", description = "Unsere Auserwählten fliegen mit Leichtigkeit über der Bastion und sorgen für Sicherheit und Wohlergehen aller im ganzen Reich.\n\nVor langer Zeit haben wir ein Netzwerk aus Animaportalen begründet, damit unsere Aspiranten, Goliaths und Provosten noch schneller durch das Reich reisen können.\n\nZieht los und aktiviert erneut dieses Netzwerk, damit auch Ihr in Windeseile dort sein könnt, wo man Euch benötigt.", sourceObjective = "Aktiviert das Transportnetzwerk.", completion = "Es ist eine Ewigkeit her, dass die Animaportale aktiv waren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63053] = { id = 63053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Windeseile", description = "Ihr müsst jetzt nicht mehr mit dem Larion im Bereich der Bastion reisen, <Schlundgänger/Schlundgängerin>.\n\nDank der jetzt wieder aktiven Portale könnt Ihr ohne Zeitverlust an alle Orte reisen, an denen Ihr gebraucht werdet.\n\nAber Ihr benötigt immer noch einen Larion, um nach Oribos zurückzukehren oder in andere Reiche zu reisen.\n\nProbiert es gleich einmal aus.", sourceObjective = "Verwendet das Ewige Tor, um an einen beliebigen Ort im Bereich der Bastion zu reisen, und dann ein beliebiges Ewiges Tor, um zur Elysischen Feste zurückzukehren.", completion = "Bald werden wir vielleicht neue Orte für unsere Portale öffnen können. Haephus kann Euch mehr dazu sagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63054] = { id = 63054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zahlenmäßige Übermacht", description = "Jede Seele in Maldraxxus hat das Potenzial, Großes zu leisten, und wir müssen so viele von ihnen zusammenbringen wie möglich, um die Ordnung in den Schattenlanden wiederherzustellen.\n\nMit diesem weiteren Mittel für das Sanktum können wir unsere Truppen mobilisieren und ihnen eine Chance verschaffen, sich selbst auf dem Schlachtfeld zu beweisen.\n\nSucht Merick Feldnarb auf. Er kümmert sich um den Einsatz unserer Soldaten.", sourceObjective = "Aktiviert den Befehlstisch.", completion = "Seid gegrüßt, {name}. Zusammen werden wir dafür sorgen, dass unsere Soldaten das Schlachtfeld dominieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63055] = { id = 63055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energie für die Portale", description = "Der Primus hat einst ein Netzwerk von Portalen unterhalten, das die Nekropolen von Maldraxxus direkt mit dem Sitz des Primus verbunden hat. Aufgrund der fehlenden Anima und der jüngsten Zerstörung vieler der Nekropolen wurden diese Verbindungen deaktiviert.\n\nMit der Anima von Euch konnten wir eines dieser Portale wieder verbinden. Ihr könnt wieder in eine unserer großartigen Nekropolen reisen... wenn sie denn noch existiert.", sourceObjective = "Aktiviert das Transportnetzwerk.", completion = "Es ist eine Ewigkeit her, dass diese Portale aktiv waren. Das ist so aufregend!", sourceObjectiveStatus = "unverified-source-field" }
quests[63056] = { id = 63056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktumaufwertung: Spiegelnetzwerk", description = "So, wir haben hier eine Schriftrolle der dunklen Ermächtigung für Euch. Damit solltet Ihr diese Spiegelrahmen herbeizaubern können. Keine große Sache.\n\nDanach braucht Ihr aber einen echten Spiegelmacher, damit sie auch funktionieren.\n\nPrinz Renathal kennt vielleicht einen Blutsauger, der sowas kann. Ihr solltet mit ihm sprechen.", sourceObjective = "Benutzt die Schriftrolle der dunklen Ermächtigung, um ein Spiegelnetzwerk zu beschwören.", completion = "Ein Netzwerk von Spiegeln, mit denen man durch das Reich reisen kann, ist von unschätzbarem Wert.\n\nGerüchten zufolge ist der früherer Spiegelmacher des Meisters erst vor Kurzem im Glutdistrikt verloren gegangen.\n\nIhr habt ja schon Euer Talent, Leute auf unsere Seite zu bringen, bewiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63057] = { id = 63057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Energie fließt wieder", description = "Anima ist Macht, {name}! \n\nAls es reichlich davon gab, hat der Primus dafür gesorgt, dass seine Soldaten so viel Anima bekamen, wie sie benötigten.\n\nJetzt, inmitten der Dürre, kämpfen die Maldraxxi untereinander um die Anima, die sie noch finden können.\n\nWenn unsere Animavorräte aufgefüllt werden, können wir sie über ganz Maldraxxus verteilen. Es unterliegt der Verantwortung von uns Nekrolords, die Pflicht des Primus in seiner Abwesenheit zu erfüllen.\n\nSprecht mit Yondare Hex. Sie wird Euch zeigen, wie das funktioniert.", sourceObjective = "Aktiviert den Animaleiter.", completion = "Lange habe ich darauf gewartet, wieder Anima über Maldraxxus zu weben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63058] = { id = 63058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ran an die Monstrositätenflickerei", description = "Die Konstrukte waren in unzähligen Kriegen das Rückgrat der maldraxxischen Armee. Ein gut konstruierter Körper kann jede Seele in eine mächtige Frontwaffe verwandeln.\n\nAußerhalb des Sanktums befindet sich ein alter Tisch für Monstrositätenflickerei, an dem wir unsere eigenen Konstrukte erschaffen könnten. Mit der Anima, die Ihr für Euren Pakt gesichert habt, lässt er sich bestimmt wiederherstellen.\n\nSobald die Arbeit begonnen hat, meldet Ihr Euch bei Miggsie im Metzgerblock.", sourceObjective = "Aktiviert die Monstrositätenfabrik.", completion = "Der Flickertisch ist repariert? Fantastisch! Bald können wir unsere eigenen Konstrukte bauen!", sourceObjectiveStatus = "unverified-source-field" }
quests[63059] = { id = 63059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Handumdrehen", description = "Einst war es ein langer Ritt auf dem Tauralus, aber jetzt nicht mehr!\n\nJetzt tretet Ihr einfach durch dieses Portal, und schon seid Ihr beim Haus der Augen.\n\nDas Haus der Augen ist vielleicht nicht mehr, was es einmal war, aber in den Ruinen ihrer einst großartigen Nekropole lassen sich immer noch einige wertvolle Verbündete finden.\n\nReist dorthin und überprüft, ob das Portal richtig funktioniert.", sourceObjective = "Reist durch das Portal Nurakkir des Hauses der Augen und kehrt dann mithilfe des Portals des Sitzes des Primus zurück.", completion = "Wenn wir weiter daran arbeiten, können wir noch mehr Portale zu anderen Nekropolen in den Schattenlanden öffnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63060] = { id = 63060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Regel 6, Fußnote: Nichts vergessen", description = "Im Schlund darf man nicht vergessen, immer alles mitzunehmen.\n\nViele Dinge kriechen durch das Bestienlabyrinth. Die Runen, die Ihr zurückgebracht habt, weisen darauf hin, dass die Mittler die dorthin gebracht wurden, etwas Nützliches zurückgelassen haben.\n\nSchaut nach, ob Ihr es finden könnt.", sourceObjective = "Haltet Ausschau nach dem, was die Mittler im Bestienlabyrinth zurückgelassen haben.", completion = "Ihr seid zurück! Bin ich froh... ich dachte schon, meine einzige Chance auf Rettung hätte sich verabschiedet.\n\nIhr rettet mich doch, oder?", sourceObjectiveStatus = "unverified-source-field" }
quests[63061] = { id = 63061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helfende Hand", description = "Wir haben vielleicht einen Flickertisch, aber ohne jemanden, der sich damit auskennt, nützt er uns gar nichts... jemanden wie Rathan!\n\nIch habe gehört, er wollte schon mit den Nekrolords sprechen. Vielleicht könnt Ihr ihn ja überreden, seine Zelte hier aufzuschlagen.\n\nMit seiner Hilfe wären unsere eigenen Konstrukte im Nu fertig!", sourceObjective = "Sprecht mit Rathan.", sourceObjectiveStatus = "unverified-source-field" }
quests[63062] = { id = 63062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leid im Überfluss", description = "<Hier wurde ein Mittlergerät zurückgelassen. Es scheint dafür genutzt worden zu sein, Energie aus Rissen von Seelenenergie zu ziehen, die in dieser Gegend aufgebrochen sind.\n\nDie Mittler hätten wohl kaum versucht, dieser Energie habhaft zu werden, wenn sie nicht einen Nutzen bergen würde. Vielleicht solltet Ihr zu Ende bringen, was sie begonnen haben.>", sourceObjective = "Füllt den Phasenschröpfer an den Seelenrissen in Detrithos und bringt ihn zu Ve'nari im Schlund zurück.", completion = "Ihr habt meinen Schröpfer gefunden. Ihr überrascht mich immer wieder, Schlundgänger.\n\nDie einzigartige Weise, wie sich Schmerz und Leid physisch im Schlund manifestieren, ist ein Rätsel... eins, das sich mit der von Euch gesammelten Energie vielleicht lösen lässt.\n\nGut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63063] = { id = 63063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktumaufwertung: Spiegelnetzwerk", description = "Wir haben hier eine Schriftrolle der dunklen Ermächtigung für Euch. Damit solltet Ihr diese Spiegelrahmen herbeizaubern können. Keine große Sache.\n\nWenn Ihr das mit der Beschwörung erledigt habt, sollte der alte Laurent die Magie wieder zum Laufen bringen können. Er kann mit diesen Glasdingern echt gut umgehen.", sourceObjective = "Benutzt die Schriftrolle der dunklen Ermächtigung, um ein Spiegelnetzwerk zu beschwören.", completion = "Ah! Endlich sind alle Werkzeuge, die ich benötige, vorhanden. Jetzt kann die echte Arbeit beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63064] = { id = 63064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktumaufwertung: Befehlstisch", description = "Wir haben hier eine Schriftrolle der dunklen Ermächtigung für Euch. Damit solltet Ihr einen Befehlstisch herbeizaubern können. Das ist nicht irgendein Tisch, sondern eines dieser magischen Dinger, mit denen Ihr von weit weg Befehle geben könnt.\n\nTaktikerin Sakaa wollte Euch unbedingt dabei unterstützen. Ich hab diesen Flügeligen nie getraut, weil die nicht nett zu uns Gräbern waren, aber wenn die in den Krieg ziehen, schlottern selbst in Maldraxxus alle Knie.", sourceObjective = "Benutzt die Schriftrolle der dunklen Ermächtigung, um einen Befehlstisch zu beschwören.", completion = "Es gibt vieles, das wir erreichen müssen, doch trotz Eures Einfallsreichtums könnt Ihr nicht überall gleichzeitig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63065] = { id = 63065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktumaufwertung: Der Gluthof", description = "Wir haben hier eine Schriftrolle der dunklen Ermächtigung für Euch. Damit solltet Ihr genug Ressourcen auftun können, um eine von den schicken Feiern zu schmeißen, auf die die Blutsauger so stehen.\n\nIhr solltet mit dem Wahnsinnigen Herzog darüber sprechen. Er hat die ganzen Hoffeierlichkeiten ausgerichtet, bevor sie ihn gegrillt haben.", sourceObjective = "Benutzt die Schriftrolle der dunklen Ermächtigung, um den Gluthof zu beginnen.", completion = "Kommt, kommt, mein Freund!\n\nEs ist Zeit... für eine FEIER!", sourceObjectiveStatus = "unverified-source-field" }
quests[63066] = { id = 63066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sanktumaufwertung: Animaleiter", description = "So, wir haben jetzt die ganze Anima, die Ihr gesammelt habt.\n\nAber die ganze Anima wurde früher aus anderen Reichen rausgequetscht. Der Meister war gut darin, alles auszuquetschen, das nicht wie er war.\n\nDeswegen haben wir eine Schriftrolle der dunklen Ermächtigung auf der unteren Ebene abgelegt. Damit solltet Ihr etwas raufbeschwören können, das stark genug ist, damit Ihr über die Distrikte von Revendreth Anima zurück in die Schattenlande kanalisieren könnt.\n\nIch glaub, das hat ein paar ganz gute Nebenwirkungen.", sourceObjective = "Benutzt die Schriftrolle der dunklen Ermächtigung, um einen Animaleiter zu beschwören.", completion = "Es ist Zeit, die Anima in den Schattenlanden wiederherzustellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63067] = { id = 63067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wurzelwiederherstellung", description = "Die Anima floss einst reichlich, aber wir dürsten seit langer Zeit. Ihr bringt uns Nahrung in Zeiten des Mangels. Wir wachsen.\n\nWir können jetzt vielleicht anderen helfen und die Gabe teilen.\n\nBeobachtet unser Wachstum und sprecht dann mit Sesselie. Sie wird Euch mehr erzählen.", sourceObjective = "Aktiviert den Animaleiter und sucht dann Sesselie auf.", completion = "Wir wachsen mit der Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63068] = { id = 63068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genug gezankt", description = "Bei meiner Suche nach dem passenden Kyrianer für unseren Aufgabe hier bin ich auf zwei Kandidaten gestoßen: Pelodis und Nemea.\n\nLeider sind sie Rivalen und verschwenden ihre Aufmerksamkeit an andere Dinge. Ich schlage vor, Ihr helft ihnen, den Zwist beizulegen, damit sie sich auf unsere dringende Aufgabe konzentrieren.\n\nZusammenarbeit kommt für sie wohl nicht infrage, also müsst Ihr einen der zwei auswählen.", sourceObjective = "Trefft Pelodis am Schmiedefeueraußenposten oder Nemea in Nemeas Zuflucht.", completion = "Ah, Ihr wollt mir bei meinem Problem helfen. Erlaubt mir, Euch meinen Weg zu demonstrieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63069] = { id = 63069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sie wissen", description = "<Dieser Mittler hat offenbar Informationen gesammelt, als ihn sein unglückliches Ende ereilte. Ve'nari wäre bestimmt sehr daran interessiert, was er herausgefunden hat.\n\nLeider haben die Tiere dieser Gegend seine Notizen überall verteilt.>", sourceObjective = "Sammelt 18 zerfledderte Tagebuchseiten in der Hungernden Ödnis und bringt sie zu Ve'nari im Schlund.", progress = "Dieses Buch... Ihr habt da das Tagebuch eines Pfadfinders!", completion = "Das Kartell Ve sucht anscheinend immer noch nach dem Schlund.\n\nMir das Tagebuch dieses Pfadfinders zu bringen war eine kluge Entscheidung. Was auch immer das Kartell über diesen Ort herausgefunden hat, wird uns mehr nützen als einer Leiche.", sourceObjectiveStatus = "unverified-source-field" }
quests[63072] = { id = 63072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschaffung: Stygisches Erz", description = "<Die Steinsäulen in dieser Region strotzen nur so von Adern leuchtenden Metalls aus einer anderen Welt.\n\nDie Schlundgebundenen haben Seelen eingesetzt, um es abzubauen, aber sie haben offenbar nicht allzu lange durchgehalten.\n\nVe'nari hätte sicherlich Verwendung für dieses Erz, wenn Ihr es irgendwie abbauen könnt.>", sourceObjective = "Sammelt 15 Stücke stygisches Erz im Markwald und bringt sie zu Ve'nari im Schlund.", progress = "Was habt Ihr da, Schlundgänger?", completion = "Faszinierend, dieses Metall scheint vollständig aus Stygia zu bestehen!\n\nDas eröffnet mir so viele Möglichkeiten. Nehmt diese Belohnung zusammen mit meinem Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[63073] = { id = 63073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Myzelnetzwerk", description = "Anima fließt in die tiefsten Wurzeln und nährt die Pilze. Schon lange reisen wir nicht mehr mit den Ringen durch den Ardenwald.\n\nStellt unsere Verbindung zum Pilznetzwerk wieder her.", sourceObjective = "Aktiviert das Transportnetzwerk.", completion = "Hmmmmmmmmmmmmmmmmm. Normalerweise sollten jetzt schon einige Pilz sprießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63100] = { id = 63100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geteiltes Leid", description = "<Die Hülle dieser armen Seele wurde allem beraubt und ist fast vollständig der Existenz entschwunden.\n\nDieses Leid muss ein Ende haben. Befreit die anderen von ihrem Elend.>", sourceObjective = "Tötet 10 hoffnungslose Gefäße in Gorgoa: Fluss der Seelen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63101] = { id = 63101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XX REUSEME", description = "So wie Euer Ruf in den Schattenlanden wächst, soll das Herz des Waldes mit Euch wachsen\n\nSucht Laurel, unsere Hüterin des Ruhms auf. Sie wird Euch mit der Magie vertraut machen, die wir unseren Jägern und Jägerinnen zuteilwerden lassen.", sourceObjective = "Sucht Laurel im Herz des Waldes auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[63132] = { id = 63132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Konstellarschriftstück", description = "<Das Geschriebene auf der Schriftrolle ändert sich schnell. Sie enthält höchstwahrscheinlich uralte Geheimnisse, die Ve'nari vielleicht interessieren könnten.>", sourceObjective = "Bringt das Konstellarschriftstück zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "<Ve'nari untersucht die Niederschrift.>\n\nEine interessante Methode, Geheimnisse festzuhalten. Es könnte schwierig werden, das zu entziffern.\n\nDanke, dass Ihr mir dies gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63133] = { id = 63133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veränderliches Kryptogramm", description = "<In die sich ständig verschiebenden Facetten des Würfels sind Runen eingearbeitet, die Ihr nicht lesen könnt.\n\nVe'nari könnte Interesse daran haben.>", sourceObjective = "Bringt das veränderliche Kryptogramm zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ah, diese Runen habe ich schon lange nicht mehr gesehen. Eine alte Mittlermethode der Verschlüsselung.\n\nDas wird sehr nützlich sein, sollte ich je Kartellgespräche abfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63134] = { id = 63134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Patrouillenkarte der Schlundgebundenen", description = "<Ein Diagramm, dass die Bewegungsmuster der Schlundgebundenen skizziert, wurde auf das Pergament gekritzelt.\n\nVe'nari könnte das nützlich finden.>", sourceObjective = "Bringt die Patrouillenkarte der Schlundgebundenen zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Wahrlich wertvolle Informationen. Damit werde ich unbemerkt bleiben, wenn ich die Sicherheit dieser Zuflucht verlassen muss.\n\nIhr habt die Patrouillen sicherlich schon verinnerlicht, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63135] = { id = 63135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaltherzflugrouten", description = "<Diese Diagramme enthalten ausführliche Informationen über die Patrouillen der schlundgebundenen Kyrianer.\n\nVe'nari würde sich über dieses Wissen freuen.>", sourceObjective = "Bringt die Kaltherzflugrouten zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Das wird den Luftvorteil der Schlundgebundenen abschwächen. Natürlich müsst Ihr trotzdem Vorsicht walten lassen.\n\nLasst sie Euch wenn möglich nicht entdecken. Es wäre ungünstig, wenn Euch einer hierher folgen würde.", sourceObjectiveStatus = "unverified-source-field" }
quests[63136] = { id = 63136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chaotische Runen", description = "<Eine Reihe unverständlicher Zeilen wurden auf antikem Pergament niedergeschrieben.\n\nVe'nari würde das schätzen.>", sourceObjective = "Bringt die chaotischen Runen zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ah, ja. Eindeutig von jemandem in den Fängen des Wahnsinns verfasst.\n\nDeswegen ist es aber noch lange kein Unsinn. Manchmal erkennen nur die Wahnsinnigen die Wahrheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63137] = { id = 63137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rätselhaftes Kryptogramm", description = "<Die Markierungen auf jeder Seite des Würfels wechseln regelmäßig ihre Positionen.\n\nDas wird Ve'nari interessieren.>", sourceObjective = "Bringt das rätselhafte Kryptogramm zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "<Ve'nari lacht, als sie das Kryptogramm mustert.>\n\nDas... ist Kinderspielzeug. Mittler benutzen sie, um die Verschlüsselungsmethoden ihres Kartells zu lehren.\n\nDas macht es aber nicht wertlos. Im Gegenteil. An so einem Ort ist der kleinste Funke Frohsinn unglaublich wertvoll.", sourceObjectiveStatus = "unverified-source-field" }
quests[63140] = { id = 63140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgegriffene Obleronradierung", description = "<Die Gravur auf dem zerfallenden Manuskript weist auf die Ursprünge des Schlundes hin.\n\nVe'nari wäre davon fasziniert.>", sourceObjective = "Bringt die abgegriffene Obleronradierung zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "<Ve'nari sieht sich das Manuskript an.>\n\nEin sehr, sehr altes Dokument. Schade, dass es in so einem schlechten Zustand ist. Seine Geheimnisse müssen unbezahlbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63142] = { id = 63142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baupläne der Seelenschmiede", description = "<Als Ihr die Dokumente in Eurem Besitz durchseht, erkennt Ihr, dass sie die schrecklichen Methoden umreißen, mit denen Seelen zu Rüstungsgütern geschmiedet werden können.\n\nDas wäre spannend für Ve'nari.>", sourceObjective = "Bringt die Baupläne der Seelenschmiede zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Rohmaterial muss im Schlund schwer zu beschaffen sein. Es überrascht mich nicht, dass die Waffenschmiede des Kerkermeisters... einfallsreich sein müssen.\n\nVielleicht sollte das Wissen in diesen Bauplänen ein Geheimnis bleiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63145] = { id = 63145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattengebundenes Zeugnis", description = "<Dies scheint die wirre Niederschrift eines von Schmerzen getriebenen Torghastgefangenen zu sein.\n\nSie dürfte für Ve'nari von Wert sein.>", sourceObjective = "Bringt das schattengebundene Zeugnis zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Was für ein Fund. Informationen aus Torghast aus erster Hand sind selten und wertvoll. Keiner, der den Turm betreten hat, ist je zurückgekehrt, um davon zu berichten.\n\nAußer Euch natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[63152] = { id = 63152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Venthyrkonkordat", description = "<Hierbei handelt es sich anscheinend um verschlüsselte Korrespondenz zwischen einem Venthyradligen und einem schlundgebundenen Leutnant.\n\nVielleicht kann Ve'nari sie entziffern.>", sourceObjective = "Bringt das Venthyrkonkordat zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "<Ve'nari sieht sich die Schriftrolle an und dreht sie in verschiedene Richtungen.>\n\nEs ist schon lange her, seit ich eine derart komplexe Methode der Verschlüsselung gesehen habe. Aber die Venthyr sind nun einmal prahlerisch.\n\nWas auch immer diese Nachricht besagt, es ist klar, dass der Verfasser sie unbedingt geheimhalten wollte.", sourceObjectiveStatus = "unverified-source-field" }
quests[63153] = { id = 63153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verworfene Qualen", description = "<Die zerfledderten und vergilbten Seiten zeigen Darstellungen von Strafen, die als zu milde empfunden und daher entsorgt wurden.\n\nVe'nari möchte sie vielleicht studieren.>", sourceObjective = "Bringt die verworfenen Qualen zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ah, ein seltener Einblick in die Gedanken der ewigen Folterknechte des Schlunds.\n\nÄußerst faszinierend... allerdings auch etwas schauderhaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[63154] = { id = 63154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schemenhundpanzerung", description = "<Das Panzerungsteil ist mit Runen bedeckt, die sich langsam und fließend bewegen.\n\nVe'nari wird daran interessiert sein, es zu untersuchen.>", sourceObjective = "Bringt die Schemenhundpanzerung zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ein wirklich interessantes Artefakt, Schlundgänger.\n\n<Ve'nari klopft sanft auf die Rüstung.>\n\nMan kann förmlich die Schreie der Seelen hören, die in die Schmiedearbeit geflossen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[63155] = { id = 63155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unentzifferbare Karte", description = "<Die Karte ist mit Kritzeleien und Anmerkungen bedeckt, die auf unbekannte Gebiete verweisen.\n\nVe'nari wird das wahrscheinlich faszinierend finden.>", sourceObjective = "Bringt die unentzifferbare Karte zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "<Ve'nari hält die Karte hoch und studiert sie genau.>\n\nUnd diese Flecken waren schon dort, als Ihr sie gefunden habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[63156] = { id = 63156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlundgebundene Fesseln", description = "<Diese teils festen, teils ätherischen Fesseln lassen Schreie in Eurem Geist erklingen, wenn Ihr sie haltet.\n\nDas ist genau die Art von Objekt, die Ve'nari sucht.>", sourceObjective = "Bringt die schlundgebundenen Fesseln zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "<Ve'nari reißt Euch die Fesseln förmlich aus den Händen.>\n\nEtwas zu gefährlich, als dass Sterbliche wie Ihr einfach so damit herumlaufen sollten.\n\n<Ve'nari hebt die Fesseln langsam hoch und senkt sie dann wieder, als wollte sie ihr Gewicht taxieren.>\n\nAllerdings muss ich zugeben... dass sie äußerst nützlich sein könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63157] = { id = 63157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schachtel der Qualen", description = "<Die perfide Spieluhr spielt eine endlose Sequenz aus dissonanten Akkorden ab.\n\nVe'nari könnte das melodisch finden.>", sourceObjective = "Bringt die Schachtel der Qualen zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Wie beruhigend.\n\n<Ve'nari wirft einen genauen Blick auf das Objekt in ihren Händen.>\n\nIch frage mich...\n\n<Ve'nari drückt auf die rautenförmige Gravur auf der Seite der Schachtel. Sie rastet ein und gibt den Blick auf ein Geheimfach mit einer kleinen Pergamentrolle frei.>\n\nNichts ist, wie es scheint, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63158] = { id = 63158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wehklagende Münze", description = "<Diese seltsame Münze scheint aus einer vergessenen Zeit zu stammen. Wenn Ihr sie haltet, hört Ihr in Eurem Geist die alptraumhaften Schreie leidender Seelen.\n\nVe'nari weiß dieses Stück vielleicht zu schätzen.>", sourceObjective = "Bringt die wehklagende Münze zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ein faszinierendes Zahlungsmittel.\n\nMich würde wirklich interessieren, wer es geprägt hat und wie...", sourceObjectiveStatus = "unverified-source-field" }
quests[63159] = { id = 63159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte des Wächters", description = "<So weit Ihr das sagen könnt, ist dies ein verblasster Abschnitt eines ausgedörrten Tagebuchs, der in Wächter Korraths Handschrift niedergeschrieben wurde.\n\nFür Ve'nari könnte er wertvoll sein.>", sourceObjective = "Bringt die Worte des Wächters zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Oft kann man wertvolle Informationen auf den Seiten des Tagebuchs eines Feindes finden. Gut, dass Ihr es an Euch gebracht habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63160] = { id = 63160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korraths Grimoire: Aleketh", description = "<Anscheinend mehrere Seiten aus einem Folianten, in dem die Kreaturen des Schlunds verstörend detailliert beschrieben werden.\n\nVe'nari wird sie zweifellos unter die Lupe nehmen wollen.>", sourceObjective = "Bringt Korraths Grimoire: Aleketh zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ich glaube, ich habe die Kreaturen, die auf diesen Seiten beschrieben werden, schon einmal gesehen. \n\nAus der Ferne natürlich. Immer aus der Ferne.", sourceObjectiveStatus = "unverified-source-field" }
quests[63161] = { id = 63161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korraths Grimoire: Belidir", description = "<Anscheinend mehrere Seiten aus einem Folianten, in dem die Kreaturen des Schlunds verstörend detailliert beschrieben werden.\n\nVe'nari wird sie zweifellos unter die Lupe nehmen wollen.>", sourceObjective = "Bringt Korraths Grimoire: Belidir zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Ah, ja. Ein herrliches Studienobjekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63162] = { id = 63162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korraths Grimoire: Gyadrek", description = "<Anscheinend mehrere Seiten aus einem Folianten, in dem die Kreaturen des Schlunds verstörend detailliert beschrieben werden.\n\nVe'nari wird sie zweifellos unter die Lupe nehmen wollen.>", sourceObjective = "Bringt Korraths Grimoire: Gyadrek zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Egal, wie lange ich schon hier bin, es gibt noch immer vieles über die Kreaturen des Schlundes, das ich nicht weiß.\n\nManchmal frage ich mich, ob es nicht besser so ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[63163] = { id = 63163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notizen des Peinigers", description = "<Die zerknitterte und angesengte Seite beschreibt die präferierten Verhör- und Unterwerfungsmethoden der Schlundgebundenen.\n\nVe'nari könnte sie interessant finden.>", sourceObjective = "Bringt die Notizen des Peinigers zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Eine äußerst lebhafte Beschreibung.\n\nIhr solltet dies als Mahnung daran werten, was passieren wird, wenn Ihr bei Euren Anstrengungen gegen den Kerkermeister versagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[63164] = { id = 63164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle der Schlundgebundenen", description = "<Das Dokument beschreibt eine Reihe von Befehlen, die von Wächter Korrath ausgegeben wurden.\n\nVe'nari wird sie bestimmt aufschlussreich finden.>", sourceObjective = "Bringt die Befehle der Schlundgebundenen zu Ve'nari in Ve'naris Zuflucht.\n\nBereitgestellter Gegenstand:", completion = "Gut gemacht, Schlundgänger. Damit können wir die Handlungen des Feindes besser absehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63166] = { id = 63166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein schemenhaftes Schicksal", description = "Die Schlundgebundenen... foltern und quälen Seelen in der Wiege des Ruins.\n\nIch... konnte mit knapper Not entkommen, aber ich fürchte, ich halte nicht lange durch.\n\nIhre grauenhaften Rituale... Sie brechen Seelen, damit sie ihnen als elende Schemen dienen.\n\nBewahrt sie vor diesem Schicksal!", sourceObjective = "Befreit 6 gepeinigte Seelen in der Wiege des Ruins, indem Ihr die Kreise der Agonie zertrampelt, die sie binden.", completion = "Ihr habt... diese Seelen vor einem furchtbaren Schicksal bewahrt.\n\nSelbst ein... wahres Ende... kann nicht schlimmer sein als diese Qual...", sourceObjectiveStatus = "unverified-source-field" }
quests[63168] = { id = 63168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Echthra", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Echthra. Sie sollen die Lektionen lernen, die ihre Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Echthra zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Echthra auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63169] = { id = 63169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Alderyn und Myn'ir", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Alderyn und Myn'ir. Sie sollen die Lektionen lernen, die ihre Erinnerungen bieten.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Alderyn und Myn'ir zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Alderyn und Myn'ir auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63170] = { id = 63170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Nuuminuuru", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Nuuminuuru. Sie sollen die Lektionen lernen, die ihre Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Nuuminuuru zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Nuuminuuru auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63171] = { id = 63171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Craven Korinth", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Craven Korinth. Sie sollen die Lektionen lernen, die seine Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Craven Korinth zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Craven Korinth auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63172] = { id = 63172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Splitterborkalptraum", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf den Splitterborkalptraum. Sie sollen die Lektionen lernen, die seine Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, den Splitterborkalptraum zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt den Splitterborkalptraum auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63173] = { id = 63173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Thran'tiok", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Thran'tiok. Sie sollen die Lektionen lernen, die ihre Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Thran'tiok zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Thran'tiok auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63174] = { id = 63174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Manischer Mortimer", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf den Manischen Mortimer. Sie sollen die Lektionen lernen, die seine Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, den Manischen Mortimer zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt den Manischen Mortimer auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63175] = { id = 63175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Athanos", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Athanos. Sie sollen die Lektionen lernen, die seine Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Athanos zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Athanos auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63176] = { id = 63176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Azaruux", description = "Eure Seelenbande brauchen Eure strategische Hilfe in einer weiteren Prüfung.\n\nDiese Woche konzentrieren sie sich auf Azaruux. Sie sollen die Lektionen lernen, die seine Erinnerung bietet.\n\nMeldet Euch bei Artemede, sobald Ihr bereit seid, und kehrt zum Pfad des Aufstiegs zurück. Helft Euren Seelenbanden dabei, Azaruux zu besiegen, um ihr Wachstum zu beweisen.", sourceObjective = "Besiegt Azaruux auf dem Pfad des Aufstiegs mit einem Seelenband.", completion = "Gratulation zum Sieg. Ich bin gespannt darauf zu hören, was Eure Seelenbande gelernt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63179] = { id = 63179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ertränkt und auseinandergerissen", description = "<Schlundgänger/Schlundgängerin>! Ich bin erleichtert, Euch hier zu sehen.\n\nEine finstere Kyrianersekte, die sich mit dem Schlund verschworen hat, hat meine Brüder und Schwestern von ihren Posten in der Bastion entführt. Sie haben uns einer garstigen Meereshexe überlassen, wie ich sie noch nie gesehen habe.\n\nDiese... Helya, glaube ich, nannten sie sie... scheint entschlossen zu sein, uns zu brechen, damit wir uns ihr anschließen.\n\nBitte rettet meine Brüder und Schwestern, wenn Ihr könnt.", sourceObjective = "Befreit 8 ertrinkende Kyrianer im Gorgoa, dem Fluss der Seelen.", completion = "Wir stehen in Eurer Schuld, Schlundgänger.\n\nIch weiß nicht, ob wir diesem Ort je entfliehen werden, aber immerhin habt Ihr uns eine Chance verschafft, zurückzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63181] = { id = 63181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nOffenbar hatte Pelagos Probleme mit seinen Prüfungen. Ich glaube, er braucht nur etwas mehr Übung auf dem Pfad unter Eurer Anleitung!\n\nAthanos hat viele Lektionen zu lehren. Mit Eurer Hilfe kann sich Pelagos den Sieg und neue Erfahrung sichern.", sourceObjective = "Besiegt Athanos als Pelagos in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63182] = { id = 63182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nPelagos' Zeit im Ardenwald hat ihn viel gelehrt. Ich würde gerne sehen, was er gelernt hat.\n\nEine Prüfung gegen Nuuminuuru sollte ihm die Möglichkeit dazu geben. Mit Eurer Hilfe kann sich Pelagos den Sieg und neue Erfahrung sichern.", sourceObjective = "Besiegt Nuuminuuru als Pelagos in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63184] = { id = 63184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nMikanikos hat um eine zusätzliche Prüfung gebeten, um Bron zu trainieren. Die Erinnerung des Splitterborkalptraums wurde mit der Hilfe seiner Prätoren eingefangen und sollte eine würdige Herausforderung für seinen Goliath bieten.\n\nMit Eurer Hilfe können Mikanikos und Bron eine weitere Prüfung bestehen.", sourceObjective = "Besiegt den Splitterborkalptraum als Mikanikos in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63185] = { id = 63185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nKleia ist bereit für eine weitere Herausforderung. Sie will unbedingt zurück auf den Pfad, um weiter ihre neuen Fähigkeiten zu üben.\n\nEchthras Erinnerung wird ihr neue Lektionen bieten. Mit Eurer Hilfe kann Kleia diese Herausforderung bezwingen und die Lehren daraus in ihre ewige Ausbildung einbinden.", sourceObjective = "Besiegt Echthra als Kleia in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63186] = { id = 63186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nKleia ist bereit für eine weitere Herausforderung. Sie will unbedingt zurück auf den Pfad, um weiter ihre neuen Fähigkeiten zu üben.\n\nWenn sie Seelen durch den Schleier geleiten soll, muss sie darauf vorbereitet sein, sich Verschlingern wie Azaruux zu stellen. Mit Eurer Hilfe kann Kleia diese Herausforderung bezwingen und die Lehren daraus in ihre ewige Ausbildung einbinden.", sourceObjective = "Besiegt Azaruux als Kleia in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63187] = { id = 63187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nMikanikos hat um eine zusätzliche Prüfung gebeten, um Bron zu trainieren. Die Erinnerung des Manischen Mortimers sollte eine schöne Herausforderung sein, da er und Mikanikos beide danach streben, ihre Forschung zu vertiefen.\n\nMit Eurer Hilfe können Mikanikos und Bron eine weitere Prüfung bestehen.", sourceObjective = "Besiegt den Manischen Mortimer als Mikanikos in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63188] = { id = 63188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nThenios hat um eine Prüfung der Weisheit gebeten, um Euer strategisches Denken und die Fähigkeiten Eurer Seelenbande zu trainieren.\n\nEine Prüfung gegen Alderyn und Myn'ir sollte ausreichen. Lasst uns sehen, wozu Ihr und Eure Seelenbande imstande seid.", sourceObjective = "Besiegt Alderyn und Myn'ir in der Prüfung der Weisheit auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63189] = { id = 63189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nThenios hat um eine Prüfung der Weisheit gebeten, um Euer strategisches Denken und die Fähigkeiten Eurer Seelenbande zu trainieren.\n\nEine Prüfung gegen Thran'tiok sollte ausreichen. Lasst uns sehen, wozu Ihr und Eure Seelenbande imstande seid.", sourceObjective = "Besiegt Thran'tiok in der Prüfung der Weisheit auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63190] = { id = 63190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nObwohl die meisten Kyrianer Vorlieben haben, muss sich jeder von ihnen mit einer Vielzahl von Waffen und Ausrüstung beweisen. Das hält ihren Verstand geschärft und ihre Muskeln und Bewegungsabläufe geschmiert.\n\nSehen wir mal, wie sich Eure Seelenbande gegen die Erinnerung von Craven Korinth mit dem Ring des Schutzes schlagen.", sourceObjective = "Besiegt Craven Korinth mit dem Ring des Schutzes in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63191] = { id = 63191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Artemedes Herausforderung", description = "Bereit für eine Herausforderung, {name}?\n\nObwohl die meisten Kyrianer Vorlieben haben, muss sich jeder von ihnen an einer Vielzahl von Waffen und Ausrüstung beweisen. Das hält ihren Verstand geschärft und ihre Muskeln und Bewegungsabläufe geschmiert.\n\nSehen wir mal, wie sich Eure Seelenbande gegen die Erinnerung von Kalisthene mit der geistgeschmiedeten Aegis schlagen.", sourceObjective = "Besiegt Kalisthene mit der geistgeschmiedeten Aegis in der Prüfung der Loyalität oder höher auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63192] = { id = 63192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfad des Aufstiegs: Prüfung der Demut", description = "Bereit für eine Herausforderung, {name}?\n\nViele Kyrianer haben mit den Prüfungen der Demut auf ihrem Pfad Schwierigkeiten. Man darf nicht vergessen, dass wir immer lernen und uns verbessern können, egal, wie weit wir gekommen sind. Doch wenn wir weiter üben, können wir mehr Hindernisse als zuvor bezwingen.\n\nEs ist Zeit, Eure Seelenbande an diese Lektion zu erinnern. Auf dass Ihr alle in einer Prüfung der Demut obsiegen mögt.", sourceObjective = "Bewältigt eine Prüfung der Demut auf dem Pfad des Aufstiegs.", completion = "Ich wusste, Ihr würdet es schaffen. Gut gemacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[63206] = { id = 63206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seelenlose Hüllen", description = "Einige der Schlundgebundenen nehmen ihren Anfang als leblose Rüstungen, die von den stygischen Schmieden in Zovaals Kessel gefertigt werden. Dann warten sie auf die Infusion eines verkommenen Schemens, um ihre Schöpfung abzuschließen.\n\nZu diesem Zeitpunkt sind sie am verwundbarsten, und genau dann müsst Ihr zuschlagen.\n\nDie Hämmer, die die schlundgebundenen Runenschmiede schwingen, können formen oder zerstören. Beschafft Euch einen und zerschmettert den Feind zu Staub, bevor er sich gegen uns erhebt.", sourceObjective = "Beschafft einen stygischen Hammer von einem stygischen Runenschmied und zerstört 10 gepanzerte Hüllen in Zovaals Kessel.", progress = "Habt Ihr unsere Feinde zu unserer Zufriedenheit zerlegt?", completion = "Ist das nicht befriedigend?\n\nJe weniger Schlundgebundene sich dem Kerkermeister anschließen, desto besser für unsere fortwährende Existenz.", sourceObjectiveStatus = "unverified-source-field" }
quests[63208] = { id = 63208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der nächste Schritt", description = "Eure Leistungen sind nicht unbemerkt geblieben, aber es gibt weitere Reiche, die Eure Hilfe benötigen.\n\nÜberlegt Euch den nächsten Schritt Eurer Reise.", sourceObjective = "Wählt, welchen Ort Ihr in den Schattenlanden aufsuchen wollt.", completion = "Eine weise Entscheidung. Sorgt dafür, dass sie Eure Hilfe schnell erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63209] = { id = 63209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorsehung fördern", description = "Es gibt noch andere Reiche, die Eure Hilfe benötigen.\n\nIhr müsst zu einem von ihnen reisen und sicherstellen, dass es standhält.\n\nWohin werdet Ihr als Nächstes gehen?", sourceObjective = "Wählt, welchen Ort Ihr in den Schattenlanden aufsuchen wollt.", completion = "Mögen Eure Mühen Früchte tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63210] = { id = 63210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der letzte Schritt", description = "Nur ein Reich ist übrig, das Eure Hilfe benötigt.\n\nSprecht mit mir, wenn Ihr bereit seid, und ich werde Euch weitere Informationen geben.\n\nDas ist der Weg der Vorsehung.", sourceObjective = "Wählt, welchen Ort Ihr in den Schattenlanden aufsuchen wollt.", completion = "Viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[63211] = { id = 63211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Adrestes", description = "Ihr habt weise gewählt.\n\nDie Kyrianer geleiten schon seit langer Zeit Seelen durch den Schleier in die Schattenlande und sorgen für einen konstanten Animafluss in alle Reiche.\n\nIhre heilige Aufgabe muss gestärkt werden. Sprecht mit Polemarch Adrestes und beginnt Eure Zukunft mit Eurem Pakt.", sourceObjective = "Meldet Euch bei Polemarch Adrestes.", completion = "Seid gegrüßt, Schlundgänger.", sourceObjectiveStatus = "unverified-source-field" }
quests[63212] = { id = 63212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Mevix", description = "Ihr habt weise gewählt.\n\nDie Nekrolords, die ewigen Beschützer der Schattenlande, müssen gestärkt werden, damit wir weiterhin die Vorsehung erfüllen können.\n\nHelft ihnen, so gut Ihr könnt. Sprecht mit Secutor Mevix und beginnt Eure Zukunft mit Eurem Pakt.", sourceObjective = "Meldet Euch bei Secutor Mevix.", completion = "Ich wusste, Ihr kommt zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[63213] = { id = 63213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ältester Naladu", sourceObjective = "Die Schulden eines Verräters können nie ganz abbezahlt werden. Aber Sühne kann mit Dienst und Schmerz geleistet werden.\n\nNehmt einen Teil meiner Macht mit Euch, Schlundgänger. Gewährt mir diesen kleinen Schritt hin zur Abbitte.", sourceObjectiveStatus = "unverified-source-field" }
quests[63214] = { id = 63214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Mondbeere", description = "Ihr habt weise gewählt.\n\nDie Nachtfae erfüllen eine wichtige Rolle im ewigen Kreislauf der Naturgeister. Das Gleichgewicht vieler Welten hängt von ihrer Arbeit ab.\n\nSprecht mit Lady Mondbeere und beginnt Eure Zukunft mit Eurem Pakt.", sourceObjective = "Meldet Euch bei Lady Mondbeere.", completion = "Ihr seid zurück! Ich wusste, dass Ihr uns wählen würdet!", sourceObjectiveStatus = "unverified-source-field" }
quests[63215] = { id = 63215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Draven", description = "Ihr habt weise gewählt.\n\nDie Venthyr müssen wieder ihre Pflicht aufnehmen, Seelen dabei zu helfen, für ihre Sünden zu büßen und sie so vor einer Ewigkeit im Schlund zu retten.\n\nDenathrius' Verrat muss richtiggestellt werden. Sprecht mit General Draven und beginnt Eure Zukunft mit Eurem Pakt.", sourceObjective = "Meldet Euch bei General Draven.", completion = "Eine weise Entscheidung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63340] = { id = 63340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran von Sündensturz", description = "Der Einfluss von Sündensturz wächst dank Eurer Siege, {name}!\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen Revendreths hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen Oribos' wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63341] = { id = 63341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker von Sündensturz", description = "Sündensturz erhält mehr Respekt, als es sich Denathrius je hätte erhoffen können! Das ist alles Eurem Einsatz zu verdanken, {name}.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst des Kartells Zo riskieren! Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht haben sie noch mehr Belohnungen, die sie Euch zuteilkommen lassen möchten.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteil kommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63342] = { id = 63342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran der Nekrolords", description = "Der Einfluss der Nekrolords wächst dank Euch, {name}!\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen Maldraxxus' hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen Oribos' wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63343] = { id = 63343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker der Nekrolords", description = "Ihr habt den Nekrolords große Ehre erwiesen. Solche Ehrerweisung erregt wiederum die Aufmerksamkeit anderer.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst von Kartell Zo riskieren! Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht hat er noch mehr Belohnungen, die er Euch zuteilwerden lassen möchte.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteil kommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63344] = { id = 63344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran der Kyrianer", description = "Die Bastion heilt dank Euch, {name}. Der Weg ist frei.\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen der Bastion hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen Oribos' wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63345] = { id = 63345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker der Kyrianer", description = "Seht Euch um, {name}. Die Elysische Feste zeigt in aller Deutlichkeit, wie weit wir gekommen sind, dank Euch.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst von Kartell Zo riskieren. Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht hat er noch mehr Belohnungen, die er Euch zuteilwerden lassen möchte.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteil kommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63346] = { id = 63346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veteran der Nachtfae", description = "Der Ardenwald ist so sicher wie schon seit Langem nicht mehr, dank Euch.\n\nEure Leistungen sind nicht unbemerkt geblieben, selbst über die Grenzen des Ardenwalds hinaus.\n\nDie Erzählungen über Eure Siege klingen in den Hallen von Oribos wider. Zo'Sorg, der Meister des Konflikts, wünscht Euch in der Enklave zu treffen.\n\nEr ist außerordentlich interessiert an der Kunst des Krieges. Ich empfehle, dass Ihr ihn nicht warten lasst.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Ah, {name}. Ich habe viele Geschichten über Eure Heldentaten auf dem Schlachtfeld gehört.\n\nEs ist mir wichtig, große Kämpfer wie Euch gut auszurüsten. Zo'dash hat meine Genehmigung, Eure Rüstungen und Waffen weiter aufzuwerten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63347] = { id = 63347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktiker der Nachtfae", description = "Eure Tapferkeit hat es dem Ardenwald ermöglicht, wieder zu wachsen. Das hat auch erneut die Aufmerksamkeit von Mittlern auf sich gezogen.\n\nZo'Sorg wünscht ein weiteres Mal Eure Anwesenheit in Oribos. Geht sofort.\n\nWir möchten nicht die Gunst des Kartells Zo riskieren. Das Vertrauen eines Mittlerklans ist nicht leicht verdient.\n\nVielleicht haben sie noch mehr Belohnungen, die sie Euch zuteilwerden lassen möchten.", sourceObjective = "Trefft Euch mit Zo'Sorg in der Enklave in Oribos.", completion = "Wie ich sehe, haben sich Eure Kampffähigkeiten weiter verbessert. Ich gehe davon aus, dass Ihr guten Nutzen aus unserem letzten Angebot gezogen habt?\n\nZo'dash wurde angewiesen, Euch nun all seine Dienstleistungen zuteil kommen zu lassen. Ich freue mich darauf, ihre Auswirkungen auf Eure Leistung zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63418] = { id = 63418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forscher vermisst", description = "Chuck erklärt, dass etwas Seltsames im Dschungel vor sich zu gehen scheint und seine Gruppe von wilden Fungianern gefangen genommen wurde.\n\nEr bittet Euch, seine Freunde zu retten und so zu helfen, die Vorfälle im Dschungel aufzuklären.", sourceObjective = "Rettet Chucks Freunde.", sourceObjectiveStatus = "unverified-source-field" }
quests[63419] = { id = 63419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporen über Sporen", description = "Chuck erklärt noch einmal, dass der Dschungel ein Eigenleben zu führen scheint und wie falsch das sei.\n\nEr bittet Euch, die Sporen von den Fungianern und den infizierten Tieren einzusammeln.\n\nChuck befürchtet, dass etwas gänzlich Unnatürliches vor sich geht.", sourceObjective = "Sammelt 12 seltsame Sporen ein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63435] = { id = 63435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempeltacheles", description = "Meine Eltern verteidigen gerade den Schrein der... Acht... Kokosnüsse...? Ich hab nicht richtig aufgepasst. Darum haben sie mich vielleicht hiergelassen.\n\nSie haben mir gesagt, ich soll mit der großen weißen Katze trainieren! Ich werde nämlich eine Ninja!\n\n<Anthea führt mehrere Tritte in Eure Richtung aus.>\n\nYa! Kya! Passt bloß auf!\n\n...\n\nMir ist so langweilig. Habt Ihr Lust auf einen Haustierkampf? Ich hab alle meine Lieblingshaustiere dabei.", sourceObjective = "Besiegt Anthea in einem Haustierkampf.", completion = "Also gut, Ihr habt gewonnen. Hier, das habe ich gegen einen der Grummel eingetauscht. Kennt Ihr die Grummel? Sie mögen es nicht, wenn ich sie hinter den Ohren kraule, aber ich tue es trotzdem! Sie sind einfach so süß!", sourceObjectiveStatus = "unverified-source-field" }
quests[63447] = { id = 63447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fürchtet kein Unglück", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", sourceObjective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Bruder, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", sourceObjectiveStatus = "unverified-source-field" }
quests[63455] = { id = 63455, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tote im Wandel", description = "Obwohl der Kerkermeister die Seelen hier seinem Willen beugt, gibt es immer noch einige, die sich ihm weiterhin widersetzen.\n\nIch werde Euch die Fähigkeit verleihen, sie in ihrem Widerstand zu unterstützen. Mittels nekrotischer Kohäsion werden wir die hier befindlichen Runen, Rüstungen und Knochen verbinden, um Körper für diese Seelen zu schaffen. Körper, die es ihnen ermöglichen, für uns und ihre Freiheit zu kämpfen!\n\nBindet die fanatischen Seelen und stellt eine Armee auf!", sourceObjective = "Setzt den Kohäsionskristall ein, um Körper für 10 trotzige Seelen zu schaffen.", completion = "Ausgezeichnet, {name}. Durch Eure Anstrengungen habt Ihr unsere Truppen verstärkt!", sourceObjectiveStatus = "unverified-source-field" }
quests[63479] = { id = 63479, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerufen von der Matriarchin", description = "Seid gegrüßt, {name}.\n\nLasst uns keine unnötigen Worte verlieren. Ihr werdet dringend in Silbermond gebraucht.\n\nWir sehen ein Wiederaufleben der Geißel in Quel'Thalas. Wenn wir die Geißel nicht unter Kontrolle bekommen, werden wir bald überrannt. Wir müssen die Stellung halten!\n\nWir treffen uns in der Halle des Blutes. Dort werdet Ihr umfassend unterrichtet.", sourceObjective = "Trefft Euch mit Lady Liadrin in Silbermond.", completion = "Gut, Ihr habt es geschafft.\n\nLasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63480] = { id = 63480, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besprechung", description = "Wir haben nicht viel Zeit.\n\nDie Geißel hat Tristessa angegriffen, und es gibt nichts, was sie aufhält.\n\nWir müssen entschlossen handeln.", sourceObjective = "Hört Euch die Besprechung an.", completion = "Wir dürfen keine Zeit verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[63481] = { id = 63481, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belagerung von Tristessa", description = "Rommath hat uns den Weg geebnet, damit wir schnell nach Tristessa gelangen. Ich warne Euch, es ist bereits ein blutiges Schlachtfeld.\n\nBenutzt das Portal. Ich werde Euch unmittelbar folgen.\n\nUnd, {name}... behaltet Salandria im Auge. Sie hat zwar in der Ausbildung hervorragende Leistungen gezeigt, aber auf diese Weise wurde sie noch nie geprüft.", sourceObjective = "Nehmt das Portal nach Tristessa.", completion = "Keine Sekunde zu früh.\n\nMachen wir uns an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[63482] = { id = 63482, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod der Geißel", description = "Ich habe die Geißel nicht mehr so zahlreich aufmarschieren sehen, seit...\n\n<Liadrin schüttelt den Kopf und nimmt wieder Haltung an.>\n\nEgal. Es hat keinen Sinn, in der Vergangenheit zu schwelgen.\n\nUnsere höchste Priorität ist, ihre Zahl so weit zu verringern, dass wir herausfinden können, was... oder wer... wirklich hinter diesem Angriff steckt.\n\nBeseitigt so viele Untote, wie Ihr könnt.", sourceObjective = "Tötet die Geißel in Tristessa.", completion = "Gute Arbeit.\n\nAber für jeden Untoten, den wir erledigen, kommen mehr. Wir müssen einen Weg finden, sie an ihrer Quelle zu stoppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63483] = { id = 63483, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magusinstallation", description = "Dies ist kein hirnloser Angriff... Ich habe den Verdacht, dass ein mächtiges Wesen die Geißel manipuliert.\n\nSeitdem der Helm der Herrschaft zerbrochen wurde, besteht die Gefahr, dass jemand anderes seinen Willen umsetzt und die Kontrolle über die Untoten übernimmt... zumindest vorübergehend.\n\nRommath und ich können helfen, Tristessa zu verteidigen, aber wir müssen diese Linien durchbrechen.\n\nRäumt eine Fläche für uns. Mal sehen, ob wir ihren Anführer herauslocken können.", sourceObjective = "Helft Aethas und Rommath, die Verteidigung in Tristessa aufzubauen.", completion = "Die Schutze sind eingerichtet. Das sollte uns eine kurze Atempause verschaffen.\n\nAber dieser San'layn beunruhigt mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[63484] = { id = 63484, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe eines Ritters", description = "Offenkundig hat dieser San'layn beschlossen, die Geißel zu benutzen, um sich auf irgendeine Weise zu stärken. Wir können ihn noch so oft ausschalten, er wird immer wiederkommen.\n\nWir brauchen eine Waffe, die ihn endgültig überwältigt.\n\nIch glaube, ich habe eine Lösung. Oben findet ihr einen neu geschmiedeten Ranseur. Er muss noch mit Magie gehärtet werden. Wir müssen sein volles Potenzial freisetzen, dann wird er unser Instrument des Lichts sein.", sourceObjective = "Beschafft den Ranseur aus dem oberen Teil von Tristessa.", progress = "Habt Ihr den Ranseur beschaffen können?", completion = "Gut. Das ist genau, was wir brauchen.\n\nJetzt ist es an der Zeit, diesen Ranseur mit ausreichend Macht auszustatten, um diesen San'layn ein für alle Mal zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[63485] = { id = 63485, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein ehrliches Herz", description = "Wenn wir Vorath besiegen wollen, müssen wir die Macht des Ranseurs verstärken. Aber wir werden keine Abstriche machen oder ihm unseren Willen aufzwingen, um das zu erreichen. Diese Lektion haben wir gelernt.\n\nDie Kyrianer der Bastion sind allerdings Meister darin, Seelen an ihren richtigen Platz zu bringen. Vielleicht werden sie uns einen Teil ihrer Macht zur Verfügung stellen.\n\nBegebt Euch zur Bastion und findet eine Möglichkeit, den Ranseur zu verstärken.", sourceObjective = "Reist zu Agthias Ruhestätte in der Bastion.", completion = "Also, wenn man zufällig sterben sollte, wäre dies wohl kein schlechter Ort dafür.\n\nDieser Kyrianer sagt, er will uns helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63486] = { id = 63486, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unbeugsamer Wille", description = "Wir haben es offensichtlich mit jemandem zu tun, der schreckliche Magie anwendet, um seinen eigenen Tod hinauszuzögern.\n\nEs gibt noch eine andere Macht, von der wir wissen, dass sie Magie auf diese Weise einsetzt. Die Maldraxxi sind mit den Fallen des Todes bestens vertraut und wissen natürlich, wie man sie umgeht. Vielleicht kennt eines der Häuser eine Möglichkeit, uns zu helfen.\n\nGeht dorthin und sucht nach der Kraft, die diese unnatürliche Schleife durchbrechen kann.", sourceObjective = "Begebt Euch zum Theater der Schmerzen in Maldraxxus.", completion = "Wir sind nicht mehr in Quel'Thalas.\n\nLasst uns das, was wir brauchen, so schnell wie möglich holen. Wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[63487] = { id = 63487, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr in die Geisterlande", description = "Was für eine Macht! Gewiss kann jetzt nicht einmal Vorath der Macht dieser Waffe widerstehen.\n\nWir haben, wofür wir in die Schattenlande gekommen sind. Der Ranseur ist bereit.\n\nLasst uns zu Lady Liadrin nach Tristessa zurückkehren. Ich hoffe, wir kommen nicht zu spät, um etwas auszurichten!", sourceObjective = "Kehrt zu Lady Liadrin in Tristessa zurück.", completion = "Jetzt, wo Ihr den ermächtigten Ranseur habt, ist es an der Zeit, auf dem Schlachtfeld unsere ganze Macht zu demonstrieren.\n\nSeid Ihr bereit?", sourceObjectiveStatus = "unverified-source-field" }
quests[63488] = { id = 63488, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich bin die Klinge des Lichts", description = "Es ist an der Zeit, all die Macht und das Training im Kampf zu erproben.\n\nNehmt den ermächtigten Ranseur und zieht eine Schneise der Zerstörung durch die Geißel!\n\nWir treffen Euch am Eingang der Todesfestung.", sourceObjective = "Verwendet den ermächtigten Ranseur, um die Geißel in der Todesschneise zu erledigen.", completion = "Er ist hier. Wir haben den Feind zurück in seinen Käfig getrieben.\n\nJetzt schicken wir ihn ins Verderben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63489] = { id = 63489, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lange überfällige Gerechtigkeit", description = "Ihr habt mit der Geißel in der Todesschneise kurzen Prozess gemacht, aber wir haben ein größeres Ziel vor Augen. Es ist an der Zeit, die Fähigkeiten Eurer Waffe gegen Vorath zu testen.\n\nLasst uns das gemeinsam beenden.", sourceObjective = "Tötet Vorath.", completion = "Es ist vollbracht. Die Geißel fängt bereits an, sich zu zerstreuen.\n\nDen Rest können wir später beseitigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63490] = { id = 63490, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutritter", description = "Die Macht des Ranseurs ist aufgebraucht, aber wir haben gewonnen! Jetzt, da Vorath besiegt ist, wird es vielleicht leichter sein, mit der Geißel fertig zu werden. Dank Euch.\n\nWir treffen uns in Silbermond. Eure Bemühungen und euer Heldentum heute werden Anerkennung finden.", sourceObjective = "Erhaltet Auszeichnungen von Lady Liadrin in Silbermond.", completion = "Glückwunsch. Das war sehr wohlverdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[63494] = { id = 63494, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Entwürfe des Ambossthans", description = "Wie ich sehe, habt Ihr ein Auge auf unsere Waffen geworfen. Ich habe sie selbst geschmiedet!\n\nBis jetzt habe ich Entwürfe für einen Stab, eine einhändige Axt und einen Schild... Ich könnte Euch welche machen, wenn Ihr möchtet!\n\nZumindest würde ich das normalerweise sagen. Leider habe ich die Entwürfe bei einer Wette unten im Grimmigen Säufer verloren. Wenn Ihr sie wiederbeschaffen könntet und auch die Materialien zusammenbekommt, kann ich Euch gerne ein paar Waffen schmieden!", sourceObjective = "Findet die Person, an die Thurgaden seine Entwürfe im Grimmigen Säufer verloren hat.", completion = "Ihr wollt mich herausfordern?", sourceObjectiveStatus = "unverified-source-field" }
quests[63498] = { id = 63498, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raufen oder Saufen", description = "Ach, Thurgaden hat Euch geschickt? Man sollte meinen, der Ambossthan wäre aus härterem Material als der Rest dieses betrunkenen Haufens. Aber da habe ich mich wohl geirrt!\n\nWenn Ihr seine Entwürfe zurückhaben wollt, müsst Ihr sie fair und anständig gewinnen.\n\nIch hab nur noch eine Frage für Euch.\n\nHauen? Oder Brauen?", sourceObjective = "Besiegt Starkarm Jarden in einem ihrer Wettbewerbe.", completion = "Ihr wart eine echte Herausforderung! Nehmt die Pläne. Ich weiß sowieso nicht, wie man sie liest!", sourceObjectiveStatus = "unverified-source-field" }
quests[63501] = { id = 63501, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das nennt man Ausborgen", description = "<Diese komplexen Pläne zeigen Thurgadens Entwürfe für seine Waffen, sind aber schwer zu entziffern. An den Rändern sind in unsauberer Handschrift Notizen hingekritzelt, die Änderungen und Anmerkungen auflisten, die Thurgaden sich selbst hinterlassen hat.\n\nZwei Notizen stechen Euch besonders ins Auge. Eine besagt, dass er sein Gravurwerkzeug an die Kernhundeausbilderin Kasea Zornesschmied ausgeliehen hat. In der anderen geht es um die Frage, wie viele Elementare an den Brauvorgängen des Grimmigen Säufers beteiligt sind.>", sourceObjective = "Findet 5 Barren der Dunkelschmiede, einen siedenden Flammenkern und den Flammenspitzgraveur in der Umgebung der Schattenschmiede.", progress = "<Thurgaden flucht und murmelt vor sich hin, wie er Jarden in ihrem nächsten Wettkampf besiegen wird.>", completion = "Ihr seid mit meinen Plänen und Materialien zurück! Ich wette, Ihr habt es Jarden ordentlich gezeigt!", sourceObjectiveStatus = "unverified-source-field" }
quests[63502] = { id = 63502, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenwaffen", description = "Nur noch ein einziger Schritt, <mein Freund/meine Gute>. Wenn Ihr mir bei dieser Arbeit helft, werdet Ihr die mächtigsten Waffen in den Händen halten, die je in den tiefsten Feuern des Schwarzfelses geschmiedet wurden!", sourceObjective = "Helft Ambossthan Thurgaden, Eure neuen Waffen herzustellen.", completion = "Diese Waffen jagen selbst einem hirnlosen untoten Koloss Angst und Schrecken ein!", sourceObjectiveStatus = "unverified-source-field" }
quests[63519] = { id = 63519, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfairer Kampf", description = "Ein feiges Aas, das sich dem Ruhm des Todes entziehen will? Pah!\n\nIch habe etwas, das ihn auf der Stelle niederstrecken wird. Aber eine solche Verbesserung erfordert jemanden, der stark genug ist, um sie richtig einzusetzen.\n\nBeweist mir Euren Mut und kämpft! Wenn Ihr Euch beweisen könnt, werde ich Euren Ranseur verstärken.", sourceObjective = "Beweist Eure Stärke gegen Kampffürstin San.", completion = "Hier, nehmt die Macht, die wir weiterentwickelt haben, und nutzt sie, um Eure hartnäckigsten Feinde zu besiegen.\n\nWenn dieser San'layn jemals hier auftaucht... Tja, dann wird er einen entsprechend herzlichen Empfang genießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63522] = { id = 63522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein faires Rennen", description = "Eine Seele, die sich weigert, den Schleier zu durchqueren, ist ein Problem, mit dem wir Kyrianer vertraut sind. Ich kann Euch helfen.\n\nDoch bevor ich Eurer Waffe diese Macht verleihe, muss ich sicherstellen, dass Ihr sie nicht missbrauchen werdet und dass Euer Herz aufrichtig ist.\n\nLasst uns ein Rennen durchführen. Läutet entlang der Strecke die Glocken. Wenn Euer Herz rein ist, werden sie Eure Geschwindigkeit erhöhen. Ihr müsst mindestens fünf Glocken rechtzeitig geläutet haben, um das Rennen abzuschließen.\n\nLasst Euch nicht von Abkürzungen ablenken. Und versucht nicht zu schummeln, um weiterzukommen, denn das wird nicht funktionieren.\n\nSeid Ihr bereit?", sourceObjective = "Tragt ein ehrliches Rennen gegen Vandellor aus.", completion = "So eine sture junge Ritterdame. Sie... scheint fast eine Erinnerung an längst vergangene Zeiten zu wecken.\n\nHier, nehmt dieses Geschenk der Macht. Ich wünsche Euch den Sieg über Euren Feind.", sourceObjectiveStatus = "unverified-source-field" }
quests[63543] = { id = 63543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nekrolordangriff", description = "Unser Angriff hat die Truppen des Kerkermeisters überrumpelt. Wir werden die Verdammnisfestung überrennen und seine Champions am Altar der Herrschaft besiegen!\n\nWir brauchen Euch, <Schlundgänger/Schlundgängerin>. Unterstützt unsere Soldaten auf dem Schlachtfeld!", sourceObjective = "Schließt 1 Quests in der Verdammnisfestung und im Antlitz des Vergessens ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[63545] = { id = 63545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Plan zusammenstellen", description = "Während Maldraxxus das Haupttor angreift, können wir mithilfe unserer Zenturionen das Seitentor einnehmen.\n\nDie Überreste vieler verderbter Zenturionen, die dem Kerkermeister zum Opfer gefallen sind, liegen überall herum. Mithilfe ihrer Teile können wir neue Zenturionen bauen, die unseren Angriff unterstützen.\n\nVersucht, die Teile zu finden, die wir für den Bau eines neuen Zenturios benötigen.", sourceObjective = "Bringt Mikanikos 3 Zenturionenteile und 15 Mechanoidbolzen.", progress = "Habt Ihr die benötigten Teile gefunden?", completion = "Das sind mehr als genug Teile für einen neuen Zenturio!", sourceObjectiveStatus = "unverified-source-field" }
quests[63576] = { id = 63576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der erste Schritt", description = "Während die Pakte sich um die Verteidigung der Schattenlande bemühen, ist der Kerkermeister in Torghast nicht untätig geblieben. Er scheint die nächste Phase seines Plans in Gang setzen zu wollen.\n\nPolemarch Adrestes hat uns beunruhigende Nachrichten aus der Elysischen Feste gebracht. Er wird von seinen Beobachtungen berichten, sobald Ihr angekommen seid.\n\nEilt Euch. Ich fürchte, die Zeit wird knapp.", sourceObjective = "Sprecht mit Polemarch Adrestes in Oribos.", progress = "Wir werden weiterkämpfen.", completion = "Anduin... jetzt ein Diener des Kerkermeisters...\n\nWir müssen sofort etwas unternehmen, {name}. Es ist an der Zeit, dass die Pakte zusammenkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63578] = { id = 63578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Ardenwald", description = "In Anbetracht des Verrats von Graf Denathrius und der Abwesenheit des Primus von Maldraxxus müssen wir davon ausgehen, dass die Winterkönigin das nächste Ziel des Kerkermeisters ist.\n\nUnd wir dürfen nicht zulassen, dass sich jemand ihres Siegels bemächtigt!\n\nDer Ardenwald hat viel durchgemacht, aber er ist ein Reich von großer und geheimnisvoller Macht. Es ist nicht immer alles so, wie es scheint.\n\nDas werden wir zu unserem Vorteil nutzen. Ganz gleich, wer die Königin angreift.", sourceObjective = "Beschützt das Siegel der Winterkönigin in der Schlacht um den Ardenwald.", completion = "Wir sind gerade so mit dem Leben davongekommen! Also, DAMIT hatte ich nicht gerechnet.\n\nAber es ist noch nicht vorbei. Wir müssen weiter auf der Hut sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[63579] = { id = 63579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Seele eines Paladins", sourceObjective = "Erobert den Überrest der Gerechtigkeit aus dem Ossuarium der Verbannten in Torghast zurück.", progress = "Seid gegrüßt, Schlundgänger. Ein Glück, dass Ihr hier seid.", completion = "Ich glaube, dieses Seelenfragment könnte der Schlüssel zu Uthers Genesung sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[63580] = { id = 63580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verwundete Erinnerungen", description = "Die Ankunft von Uthers verwundeter Seele war Auslöser für viele Ereignisse, die zu unseren aktuellen Kämpfen geführt haben.\n\nDevos' gebrochenes Vertrauen. Ihre Verwicklung mit Helya. Der Aufstieg der Verschmähten.\n\nDie Bastion muss sich ändern, aber wir haben uns schwergetan, eine Lösung zu finden.\n\nVielleicht wird uns dieses Seelenfragment wertvolle Erkenntnisse liefern.", sourceObjective = "Helft Uther, eine Verbindung zum Überrest der Gerechtigkeit herzustellen.", progress = "Ich habe noch nie eine Seele gesehen, die so in Stücke gerissen wurde wie Uthers.", completion = "Uthers Seele leidet, aber wir dürfen die Hoffnung nicht aufgeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[63581] = { id = 63581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins Licht treten", description = "Es ist, wie ich befürchtet hatte.\n\nDieses Fragment von Uthers Seele wurde von der Gramklinge, die ihn tötete, verfinstert. Seine Erinnerungen sind zersplittert und verzerrt.\n\nDamit Uther sich von dem Schmerz befreien und seine Trauer überwinden kann, muss er seine Vergangenheit erneut durchleben.\n\nAber er muss es nicht allein tun.\n\nMit meinem Seelenspiegel können wir Uther auf seinem Weg durch diese Erinnerungen leiten, damit er seinen Frieden mit all den Gefühlen machen kann, die darin enthalten sind. Wir müssen ihm helfen, diese Trugbilder zu durchschauen und ihre Wahrheit zu erkennen.", sourceObjective = "Verwendet den Seelenspiegel, um Uther zu helfen, seine Vergangenheit zu durchleben.", completion = "Seine Erinnerungen sind entstellt und verworren.\n\nEs tut mir leid, Uther, aber wir müssen fortfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[63582] = { id = 63582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Er war mein Schüler", description = "Uthers Erinnerungen an diesen Prinz Arthas verfolgen ihn unerbittlich. Er ist der Grund für die Fragmentierung von Uthers Seele und Devos' Schicksal.\n\nDer Schmerz in diesen Erinnerungen ist spürbar.\n\nWir müssen noch tiefer graben. Uther muss sich der Quelle dieser Finsternis stellen.\n\nIhr müsst Euch noch einmal in seine Vergangenheit begeben, um seine Zukunft zu schützen.", sourceObjective = "Helft Uther, seine zweite Erinnerung zu durchleben.", completion = "Der Stachel des Verrats trifft Uther tief. Aber er kann es durchstehen.\n\nEr muss!", sourceObjectiveStatus = "unverified-source-field" }
quests[63583] = { id = 63583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich beabsichtige, ewig zu leben", description = "{name}, bitte. Ich bin noch nicht fertig.\n\nEs gibt noch eine weitere Erinnerung, die ich mir anschauen muss. Eine weitere, der ich mich stellen muss.\n\nEs... Es wird nicht leicht. Ich benötige weiterhin Hilfe von Euch allen.\n\nAber es muss getan werden.", sourceObjective = "Helft Uther, seine letzte Erinnerung zu durchleben.", completion = "<Adrestes reißt sich von seinen Gedanken los. Seine Augen umspielt ein entschlossener Ausdruck.>\n\nIch glaube, diese Erfahrung war das fehlende Stück für Uther. Und auch für mich.", sourceObjectiveStatus = "unverified-source-field" }
quests[63584] = { id = 63584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine triumphale Rückkehr", description = "Dieser Tempel stellt einen neuen Anfang für die Bastion dar, {name}.\n\nDer Tempel der Hingabe wird als Ort der Verbundenheit dienen. Wir werden mit den Verschmähten, den Aspiranten und Kyrianern aller Erfahrungsstufen und Hintergründe zusammenarbeiten, um eine Zukunft zu schaffen, auf die alle stolz sein können.\n\nLasst uns in die Elysische Feste zurückkehren. Ich möchte, dass Ihr Euch uns zu einem bedeutsamen Anlass anschließt: dem Aufstieg eines neuen Paragons und der Erschaffung eines neuen Siegels.", sourceObjective = "Trefft Kalisthene bei der Elysischen Feste.\n\nDie kyrianische Kurierin kann Euch hinfliegen.", completion = "Erlaubt mir, Euch zu den Spitzen des Aufstiegs zu begleiten, {name}.\n\nAls neue Polemarch der Bastion wäre es mir eine Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[63585] = { id = 63585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blinde Loyalität", description = "Der weitere Pfad der Kyrianer liegt jetzt klar vor mir.\n\nAber zunächst müssen wir mit Nikolon sprechen. Ich bitte Euch eindringlich, zu bleiben und zuzuhören.\n\nAnschließend müssen wir zur Elysischen Feste zurückkehren.\n\nIch werde dort um eine Audienz bei der Archon bitten und ich brauche Euch alle dabei an meiner Seite.", sourceObjective = "Schließt Euch Polemarch Adrestes an der Elysischen Feste für eine Audienz bei der Archon an.", progress = "Die Kyrianer müssen einen neuen Pfad ebnen.", completion = "<Adrestes neigt tief den Kopf.>\n\nEs ist mir eine Ehre. Aber wir haben gerade erst begonnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63586] = { id = 63586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitfühlende Hingabe", description = "Unser erster Tagesordnungspunkt ist die Umwidmung des Tempels der Loyalität.\n\nPelagos hat sich angeboten, hierzubleiben und bei der Vorbereitung der Zeremonie zu helfen. Ich habe Nikolon gebeten, uns mit seinen Gefährten in der Provostenrast zu treffen, um uns zu helfen, einige der Verschmähten von unserem neuen Pfad zu überzeugen.\n\nTrefft uns dort, wenn es Euch möglich ist.", sourceObjective = "Trefft Adrestes bei der Provostenrast.", completion = "Lasst uns anfangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63587] = { id = 63587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückgewinnbare Anima", description = "Mikanikos hat mir viel über die Zenturionen der Verschmähten erklärt, {name}.\n\nIch kann nicht behaupten, dass ich alles verstanden habe, aber es scheint, dass er bislang noch keinen zuverlässigen Weg gefunden hat, sie wieder in ihren regulären Betriebsmodus zu versetzen.\n\nAber ihre Anima könnte dennoch hilfreich sein!\n\nAdrestes hat sich auf die Umwidmung des Tempels konzentriert, aber nicht auf seine eigene Sicherheit. Ich fürchte, der Prozess wird ihm viel seiner Anima rauben.\n\nWenn es Euch gelingt, Kerne von den Zenturionen der Verschmähten zu besorgen, könnten wir diese als Animavorrat für Adrestes verwenden.", sourceObjective = "Sammelt 5 besudelte Zenturionenkerne von den Zenturionen der Verschmähten ein.", progress = "Ich habe mit Mikanikos an Methoden gearbeitet, um Anima von den Zenturionen der Verschmähten wiederzuverwenden. Ich kann das schaffen!", completion = "Ich danke Euch, {name}. Wenn Adrestes geschwächt sein sollte, habe ich jetzt die Anima, um ihn wieder zu stärken.", sourceObjectiveStatus = "unverified-source-field" }
quests[63588] = { id = 63588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertrauen zurückgewinnen", description = "Die Verschmähten sind Verlorene, {name}.\n\nSie sind wie Geister, die durch den Tempel der Loyalität streifen. Sie können nirgendwo anders hin. Sie sind ohne Führung, ohne Aufgabe und verlassen.\n\nWir müssen ihnen einen Pfad aufzeigen.\n\nGestattet mir, Euch in den Tempel zu begleiten, um mit ihnen zu reden und ihre Gefühle anzusprechen. Vielleicht können wir sie überzeugen, Adrestes' neuem Pfad eine Chance zu geben.", sourceObjective = "Überzeugt 10 Verschmähte, zum Pfad zurückkehren.", progress = "Die Verschmähten sind vielleicht vom Pfad abgekommen, aber wir hatten unsere Gründe.", completion = "Es wird Zeit und viele Worte brauchen, um das verloren gegangene Vertrauen wiederherzustellen, {name}... Aber es gibt wieder Hoffnung.", sourceObjectiveStatus = "unverified-source-field" }
quests[63589] = { id = 63589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hingabe hervorbringen", description = "Die fünf Tempel der Bastion haben seit ihrer Erschaffung standgehalten. Die Idee, einen von ihnen umzuwidmen, wurde noch nie angedacht und wird zweifelsohne eine erhebliche Menge Anima erfordern.\n\nUnter diesem Tempel befinden sich Vorräte an Anima, die wir für die Dürre rationiert haben. Jetzt, wo die Anima zurückkehrt, können wir diese Reserven für unsere Zwecke nutzen.\n\nIhr werdet Kanalisierer und Sammler auf dem gesamten Gelände einsetzen müssen, um die Anima nach oben zu leiten. Das sollte mir die benötigte Kraft geben.", sourceObjective = "Leitet die Anima von der Zitadelle der Loyalität zum Tempel um.", completion = "Es ist ermutigend, wieder so viel Anima fließen zu sehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63590] = { id = 63590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Vesperglockenläuten", description = "Loyalität soll nicht länger ein obligatorischer Grundsatz des Pfades sein, sondern eher ein Wert, den man sich verdient... eine Wahlmöglichkeit.\n\nWir müssen uns um jene kümmern, die zu kämpfen haben, seien es kürzlich eingetroffene Seelen oder Gleichgesinnte, die unsere Hilfe brauchen.\n\nEs wird jegliche Anima brauchen, über die wir verfügen, um diesen Tempel umzuwidmen und somit ein neues Zeitalter für die Kyrianer einzuläuten.\n\nIch fürchte, dass die Schlundgebundenen versuchen werden, unsere Pläne zu durchkreuzen. Beschützt mich während des Rituals, {name}. Wir müssen es zu Ende bringen.", sourceObjective = "Beschützt Polemarch Adrestes, während er den Tempel der Loyalität umwidmet.", progress = "<Adrestes lässt sich nicht ablenken, während er sich voll und ganz auf die anstehende Aufgabe konzentriert.>", completion = "Hingabe... wird aus Mitgefühl geboren, aus dem Geben.\n\nEin wahrhaft würdiger Grundsatz...", sourceObjectiveStatus = "unverified-source-field" }
quests[63591] = { id = 63591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der große Empfang", description = "{name}, Ihr habt den Kyrianern in diesen äußerst schwierigen Zeiten beigestanden. Eure hingebungsvolle Unterstützung hat uns allen zu einem Neuanfang verholfen.\n\nWir würden uns freuen, wenn Ihr vor der Zeremonie an einer Versammlung mit uns teilnehmen würdet. Viele Mitglieder unseres Paktes möchten ihre Wertschätzung für alles, was Ihr getan haben, zum Ausdruck bringen.\n\nDies ist ein Tag großer Freude. Ich bin sehr froh, dass Ihr hier seid und ihn miterleben könnt!", sourceObjective = "Sprecht mit Kalisthene, um an dem Treffen teilzunehmen. Mischt Euch dann unter Eure Seelenbande und die anderen Kyrianer.", completion = "Die Zeit der Zeremonie ist gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63592] = { id = 63592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Neue Pfad", description = "Heute wird ein neues Paragon ernannt. Und zum ersten Mal seit den Anfängen unseres Reiches wird ein Tempel umgewidmet, um unsere Hingabe zueinander zu repräsentieren.\n\nEin neues Paragon, ein neues Siegel und ein neuer Pfad für alle Kyrianer.\n\nDas wird eine prachtvolle Zeremonie!", sourceObjective = "Sprecht mit Kalisthene, um an der Zeremonie am Sitz der Archon teilzunehmen.", completion = "Diese Ehre ist mehr, als ich mir erhoffen konnte.\n\nEs liegt ein langer Weg vor uns, aber mit der Hilfe der Kyrianer, aller Kyrianer, wird der Tempel der Hingabe die Zukunft unseres Volkes verkörpern.\n\nLasst uns mit der wahren Arbeit beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63593] = { id = 63593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neues Siegel der Kyrianer", description = "Nun, da eine Zukunft der Gemeinschaft und Hingabe für die Bastion gesichert ist, ist ein neues Siegel geboren, das unseren weiteren Pfad repräsentiert.\n\nBitte berichtet dem Primus von all Euren Taten. Wenn er bereit ist, werdet wir ihm das Siegel bringen.\n\nHoffen wir, dass er damit den Plan des Kerkermeisters vereiteln und die Schattenlande retten kann.", sourceObjective = "Erstattet dem Primus in Korthia Bericht.", completion = "Kyrestia war die Erste, die von den Schwingen der Pflicht und des Dienstes emporgehoben wurde.\n\nDass Ihr der Archon geholfen habt, einen neuen Pfad nach vorn zu erkennen, ist in der Tat eine wundersame Sache, Sterblicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[63594] = { id = 63594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufräumarbeiten an den Mauern", description = "<Diese Schriftrolle zeigt die Standorte einer Reihe von Pylonen, die die Verdammnisfestung vor Angriffen schützen.\n\nDie Zerstörung dieser Pylonen könnte zum Erfolg unseres Angriffs beitragen.>", sourceObjective = "Nutzt den überladenen Champion, um 6 Totenseelenpylonen entlang der Mauern der Verdammnisfestung zu vernichten.", completion = "Die Verteidigung ist zusammengebrochen! Ausgezeichnete Arbeit, Schlundgänger!", sourceObjectiveStatus = "unverified-source-field" }
quests[63603] = { id = 63603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yakseele", description = "<Die Yakseele ist herzlich und widerstandsfähig. Ihr könnt jetzt die Gestalt des Yaks nutzen.>", sourceObjective = "Bringt die Yakseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, das Yak. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[63604] = { id = 63604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaufelhauerseele", description = "<Die Schaufelhauerseele ist entschlossen und hat einen ausgeprägten Beschützerinstinkt. Ihr könnt jetzt die Gestalt des Schaufelhauers nutzen.>", sourceObjective = "Bringt die Schaufelhauerseele zu Lady Muunn im Herz des Waldes.\n\nBereitgestellter Gegenstand:", completion = "Ah, der Schaufelhauer. Ihr könnt seine Gestalt nun nutzen.", sourceObjectiveStatus = "unverified-source-field" }
